insert into public.components (external_id, simplified, traditional, name_en, name_id, meaning_en, meaning_id, mnemonic_en, mnemonic_id, examples, order_index, tags, is_reviewable) values
  ('component_person_side', '亻', '亻', 'person side', 'orang di samping', 'person', 'orang', 'A person standing sideways — slim, upright, two legs. Spot this and think *person*.', '亻 kayak siluet *orang* berdiri dari samping — kurus, tegak, dua kaki.', array['你', '他']::text[], 1, array['common_component']::text[], false),
  ('component_mouth', '口', '口', 'mouth', 'mulut', 'mouth / opening', 'mulut / bukaan', 'A small open square — the shape of a *mouth* ready to speak.', '口 kotak kecil terbuka — persis bentuk *mulut* waktu mau ngomong.', array['吗', '喝']::text[], 2, array['common_component']::text[], false),
  ('component_woman', '女', '女', 'woman', 'perempuan', 'woman', 'perempuan', 'A *woman* sitting gracefully with folded arms — elegant and composed.', '女 kayak sosok *perempuan* duduk anggun dengan tangan terlipat.', array['好', '她']::text[], 3, array['common_component']::text[], false),
  ('component_child', '子', '子', 'child', 'anak', 'child', 'anak', 'A *child* with arms stretched wide, asking to be picked up.', '子 kayak *anak* kecil yang tangannya direntangkan minta digendong.', array['好']::text[], 4, array['common_component']::text[], false)
insert into public.hanzi (external_id, simplified, traditional, meaning_en, meaning_id, accepted_meanings_en, accepted_meanings_id, blocked_meanings_en, blocked_meanings_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_number, tone_pattern, mnemonic_en, mnemonic_id, tone_mnemonic_en, tone_mnemonic_id, audio_url, examples, order_index, tags, is_reviewable) values
  ('hanzi_wo', '我', '我', 'I / me', 'aku / saya', array['I / me']::text[], array['aku / saya']::text[], array[]::text[], array[]::text[], 'wǒ', 'wo3', '[{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, 3, '3', 'A fist pressed to the chest — this is *me*, not anyone else. wǒ ≈ "woh!" like spotting yourself in the mirror. Tone 3 dips then rises, like "hmm.. oh right!"', 'Tangan mengepal, nunjuk dada sendiri — ini *aku*, bukan orang lain. wǒ ≈ "woh!" kayak kaget lihat diri sendiri di cermin. Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array['[object Object]', '[object Object]']::text[], 1, array['pronoun', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_ni', '你', '你', 'you', 'kamu', array['you']::text[], array['kamu']::text[], array[]::text[], array[]::text[], 'nǐ', 'ni3', '[{"hanzi":"你","text":"nǐ","tone":3}]'::jsonb, 3, '3', 'A 亻 person standing there, and you point straight at them — that''s *you*. nǐ ≈ "knee" — you''re pointing at their knee. Tone 3 dips then rises, like "hmm.. oh right!"', '亻 orang berdiri di sana, kamu nunjuk langsung ke arahnya — itu *kamu*. nǐ ≈ "nih" kayak "nih, kamu!" Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array['[object Object]', '[object Object]']::text[], 2, array['pronoun', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_shi', '是', '是', 'to be / is', 'adalah', array['to be / is']::text[], array['adalah']::text[], array[]::text[], array[]::text[], 'shì', 'shi4', '[{"hanzi":"是","text":"shì","tone":4}]'::jsonb, 4, '4', 'The character that declares something *is* what it is — firm and final. shì ≈ "sure!" like saying "yes, that''s it!" Tone 4 drops sharp, certain and done.', 'Ini karakter yang bilang sesuatu *adalah* apa adanya — pernyataan tegas. shì ≈ "shr!" kayak bilang "iya, itu dia!" Nada 4 turun tajam, pasti dan final.', null, null, null, array['[object Object]', '[object Object]']::text[], 3, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_you_have', '有', '有', 'have / exist', 'punya / ada', array['have / exist']::text[], array['punya / ada']::text[], array[]::text[], array[]::text[], 'yǒu', 'you3', '[{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, 3, '3', 'A hand gripping something tightly — this is mine, I *have* it. yǒu ≈ "yo!" like "yo, I''ve got it!" Tone 3 dips then rises, like finding what you were looking for.', 'Tangan megang sesuatu erat-erat — ini *punya*, ini milikku. yǒu ≈ "yo!" kayak "yo, ini ada!" Nada 3 turun terus naik, kayak nemuin sesuatu yang dicari.', null, null, null, array['[object Object]', '[object Object]']::text[], 4, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_bu', '不', '不', 'not', 'tidak', array['not']::text[], array['tidak']::text[], array[]::text[], array[]::text[], 'bù', 'bu4', '[{"hanzi":"不","text":"bù","tone":4}]'::jsonb, 4, '4', 'A hand raised, head shaking — *no*, stop right there. bù ≈ "boo!" like booing something off stage. Tone 4 drops sharp, firm and final.', 'Tangan diangkat, kepala geleng — *tidak*, jangan dilanjut. bù ≈ "bu!" kayak penolakan yang keluar langsung. Nada 4 turun tajam, tegas dan final.', null, null, null, array['[object Object]', '[object Object]']::text[], 5, array['negation', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_hao', '好', '好', 'good / okay', 'baik / oke', array['good / okay']::text[], array['baik / oke']::text[], array[]::text[], array[]::text[], 'hǎo', 'hao3', '[{"hanzi":"好","text":"hǎo","tone":3}]'::jsonb, 3, '3', '女 mom watches her 子 child take their first steps — everything is *good*. hǎo ≈ "how" — how good is that! Tone 3 dips then rises, like a gasp turning into a cheer.', '女 ibu ngeliat 子 anaknya jalan pertama kali, semuanya *baik*-baik aja. hǎo ≈ "hao!" Nada 3 turun terus naik, kayak "hmm.. oh iya!"', null, null, null, array['[object Object]', '[object Object]']::text[], 6, array['adjective', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_qu', '去', '去', 'go', 'pergi', array['go']::text[], array['pergi']::text[], array[]::text[], array[]::text[], 'qù', 'qu4', '[{"hanzi":"去","text":"qù","tone":4}]'::jsonb, 4, '4', 'Feet moving forward, leaving the place behind — *going*. qù ≈ "choo!" like a train leaving. Tone 4 drops sharp, decision made.', 'Kaki bergerak maju, pergi meninggalkan tempat — dia *pergi*. qù ≈ "chu!" kayak langkah yang tegas keluar pintu. Nada 4 turun tajam, kayak keputusan udah bulat.', null, null, null, array['[object Object]', '[object Object]']::text[], 1, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_lai', '来', '來', 'come', 'datang', array['come']::text[], array['datang']::text[], array[]::text[], array[]::text[], 'lái', 'lai2', '[{"hanzi":"来","text":"lái","tone":2}]'::jsonb, 2, '2', 'Someone waving from a distance, walking toward you — *coming*. lái ≈ "lie" — they''re lying down coming to you. Tone 2 rises, like "are you here yet?"', 'Seseorang melambai dari jauh, mendekat ke arahmu — dia *datang*. lái ≈ "lai!" kayak panggilan "sini!" Nada 2 naik terus, kayak nanya "udah sampe?"', null, null, null, array['[object Object]', '[object Object]']::text[], 2, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_kan', '看', '看', 'look / see', 'lihat', array['look / see']::text[], array['lihat']::text[], array[]::text[], array[]::text[], 'kàn', 'kan4', '[{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, 4, '4', 'A hand above the eyes, scanning the horizon — *looking*. kàn ≈ "con!" like "come on, look!" Tone 4 drops sharp, like a cue.', 'Tangan di atas mata, fokus ke satu arah — sedang *lihat*. kàn ≈ "kan!" kayak bilang "coba lihat!" Nada 4 turun tajam, kayak aba-aba.', null, null, null, array['[object Object]', '[object Object]']::text[], 3, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_xiang', '想', '想', 'want / think', 'ingin / pikir', array['want / think']::text[], array['ingin / pikir']::text[], array[]::text[], array[]::text[], 'xiǎng', 'xiang3', '[{"hanzi":"想","text":"xiǎng","tone":3}]'::jsonb, 3, '3', 'Thoughts drifting, something keeps coming back — *want* or *miss*. xiǎng ≈ "shyung" like a longing sigh. Tone 3 dips then rises, like nostalgia surfacing.', 'Pikiran melayang-layang, ada sesuatu yang terus diingat — lagi *mau* atau *kangen*. xiǎng ≈ "syang" kayak "sayang" tapi pendek. Nada 3 turun terus naik, kayak nostalgia yang tiba-tiba muncul.', null, null, null, array['[object Object]', '[object Object]']::text[], 4, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_chi', '吃', '吃', 'eat', 'makan', array['eat']::text[], array['makan']::text[], array[]::text[], array[]::text[], 'chī', 'chi1', '[{"hanzi":"吃","text":"chī","tone":1}]'::jsonb, 1, '1', '口 mouth wide open, ready to chew — time to *eat*. chī ≈ "chrrr" flat, like the sound of chewing steadily. Tone 1 high and flat.', '口 mulut terbuka lebar, siap ngunyah — waktunya *makan*. chī ≈ "chi" flat kayak suara sendok ketemu piring. Nada 1 tinggi rata, kayak suara yang stabil.', null, null, null, array['[object Object]', '[object Object]']::text[], 5, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_he', '喝', '喝', 'drink', 'minum', array['drink']::text[], array['minum']::text[], array[]::text[], array[]::text[], 'hē', 'he1', '[{"hanzi":"喝","text":"hē","tone":1}]'::jsonb, 1, '1', '口 mouth open, liquid going in — *drinking*. hē ≈ "huh" flat, like a satisfied sigh after a sip. Tone 1 high and steady.', '口 mulut terbuka, cairan masuk — lagi *minum*. hē ≈ "huh" tapi rata, kayak suara puas abis teguk air. Nada 1 tinggi rata, tenang dan pasti.', null, null, null, array['[object Object]', '[object Object]']::text[], 6, array['verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_ma', '吗', '嗎', 'question particle', 'partikel tanya', array['question particle']::text[], array['partikel tanya']::text[], array[]::text[], array[]::text[], 'ma', 'ma0', '[{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, 0, '0', '口 mouth open, waiting for an answer — this character *asks*. ma is light at the end of a sentence, like a question hanging in the air. Tone 0 neutral and brief.', '口 mulut terbuka, nunggu jawaban — ini karakter yang *nanya*. ma ringan di ujung kalimat, kayak nada tanya yang gantung. Nada 0 netral, pendek, numpang lewat.', null, null, null, array['[object Object]', '[object Object]']::text[], 1, array['particle', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_ne', '呢', '呢', 'and you / what about', 'bagaimana dengan', array['and you / what about']::text[], array['bagaimana dengan']::text[], array[]::text[], array[]::text[], 'ne', 'ne0', '[{"hanzi":"呢","text":"ne","tone":0}]'::jsonb, 0, '0', '口 mouth half open, casually tossing the question back — "*what about you*?" ne is soft at the end. Tone 0 light and easy.', '口 mulut setengah terbuka, nanya balik dengan santai — kayak "*kamu* gimana?" ne ringan di ujung, kayak lempar pertanyaan balik. Nada 0 netral dan ringan.', null, null, null, array['[object Object]', '[object Object]']::text[], 2, array['particle', 'beginner']::text[], true),
  ('hanzi_shei', '谁', '誰', 'who', 'siapa', array['who']::text[], array['siapa']::text[], array[]::text[], array[]::text[], 'shéi', 'shei2', '[{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, 2, '2', 'A 讠 voice calling out, eyes scanning the room — *who* is that? shuí ≈ "shway" like a puzzled "who?" Tone 2 rises, like the question is still unanswered.', '讠 ucapan keluar sambil mata nyari-nyari — *siapa* ini? shuí ≈ "shway" kayak nanya bingung. Nada 2 naik terus, kayak pertanyaan yang belum terjawab.', null, null, null, array['[object Object]', '[object Object]']::text[], 3, array['question_word', 'beginner']::text[], true),
  ('hanzi_shen', '什', '什', 'what part', 'bagian apa', array['what part']::text[], array['bagian apa']::text[], array[]::text[], array[]::text[], 'shén', 'shen2', '[{"hanzi":"什","text":"shén","tone":2}]'::jsonb, 2, '2', 'Half of a question — meaningless alone, needs 么 to become *what*. shén ≈ "shun" rising. Tone 2 goes up, like a question hanging open.', 'Karakter setengah dari kata tanya — sendirian belum bermakna, butuh 么 untuk jadi *apa*. shén ≈ "shen" kayak "then" tapi lebih depan. Nada 2 naik, kayak pertanyaan yang menggantung.', null, null, null, array['[object Object]']::text[], 4, array['question_part', 'beginner']::text[], true),
  ('hanzi_me', '么', '麼', 'what suffix', 'akhiran apa', array['what suffix']::text[], array['akhiran apa']::text[], array[]::text[], array[]::text[], 'me', 'me0', '[{"hanzi":"么","text":"me","tone":0}]'::jsonb, 0, '0', '什''s loyal partner — only becomes *what* when joined as 什么. me is light, riding behind 什. Tone 0 neutral.', 'Pasangan setia 什 — dua-duanya baru jadi *apa* kalau digabung jadi 什么. me ringan, numpang di belakang 什. Nada 0 netral.', null, null, null, array['[object Object]']::text[], 5, array['question_part', 'beginner']::text[], true),
  ('hanzi_na', '哪', '哪', 'which / where', 'yang mana / mana', array['which / where']::text[], array['yang mana / mana']::text[], array[]::text[], array[]::text[], 'nǎ', 'na3', '[{"hanzi":"哪","text":"nǎ","tone":3}]'::jsonb, 3, '3', '口 mouth asking while pointing in no clear direction — *which* one? nǎ ≈ "nah" like "nah, which one?" Tone 3 dips then rises, like confusion becoming clarity.', '口 mulut nanya sambil nunjuk ke arah yang tidak pasti — *mana* sih? nǎ ≈ "na" kayak "nah, yang mana?" Nada 3 turun terus naik, kayak bingung lalu sadar.', null, null, null, array['[object Object]']::text[], 6, array['question_word', 'beginner']::text[], true),
  ('hanzi_jin', '今', '今', 'now / current', 'sekarang / saat ini', array['now / current']::text[], array['sekarang / saat ini']::text[], array[]::text[], array[]::text[], 'jīn', 'jin1', '[{"hanzi":"今","text":"jīn","tone":1}]'::jsonb, 1, '1', 'The day right in front of you, not yesterday not tomorrow — *now*, *today*. jīn ≈ "jean" flat like a steady clock. Tone 1 high and even.', 'Hari yang ada di depan mata, bukan kemarin bukan besok — *sekarang* ini. jīn ≈ "jin" flat kayak hari yang berjalan tenang. Nada 1 tinggi rata, stabil kayak jarum jam.', null, null, null, array['[object Object]']::text[], 1, array['time', 'beginner']::text[], true),
  ('hanzi_tian', '天', '天', 'day / sky', 'hari / langit', array['day / sky']::text[], array['hari / langit']::text[], array[]::text[], array[]::text[], 'tiān', 'tian1', '[{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, 1, '1', 'The wide sky above — one full *day* from morning to night. tiān ≈ "tyen" flat and open. Tone 1 high and steady, like a sky that stretches.', 'Langit luas di atas — satu *hari* penuh dari pagi ke malam. tiān ≈ "tyen" flat dan luas. Nada 1 tinggi rata, kayak langit yang membentang.', null, null, null, array['[object Object]']::text[], 2, array['time', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_ming', '明', '明', 'bright / tomorrow part', 'terang / bagian besok', array['bright / tomorrow part']::text[], array['terang / bagian besok']::text[], array[]::text[], array[]::text[], 'míng', 'ming2', '[{"hanzi":"明","text":"míng","tone":2}]'::jsonb, 2, '2', '日 sun + 月 moon shining together — *bright*, full of hope, like *tomorrow*. míng ≈ "ming" rising like a sunrise. Tone 2 climbs, like morning energy.', '日 matahari + 月 bulan bersinar bareng — *terang* dan penuh harapan, kayak hari *besok*. míng ≈ "ming" naik kayak matahari terbit. Nada 2 naik terus, kayak semangat pagi.', null, null, null, array['[object Object]']::text[], 3, array['time', 'beginner']::text[], true),
  ('hanzi_xian', '现', '現', 'current', 'saat ini', array['current']::text[], array['saat ini']::text[], array[]::text[], array[]::text[], 'xiàn', 'xian4', '[{"hanzi":"现","text":"xiàn","tone":4}]'::jsonb, 4, '4', 'Something appearing, real and right in front of you — *right now*, not later. xiàn ≈ "shyen!" sharp. Tone 4 drops fast, like "here it is, now!"', 'Sesuatu yang muncul dan nyata di depan mata — ini *saat ini*, bukan nanti. xiàn ≈ "syen!" tegas. Nada 4 turun tajam, kayak "ini dia, sekarang!"', null, null, null, array['[object Object]']::text[], 4, array['time', 'beginner']::text[], true),
