  ('hanzi_qian_front', '前', '前', 'front / ahead', 'depan', array['front / ahead']::text[], array['depan']::text[], array[]::text[], array[]::text[], 'qián', 'qian2', '[{"hanzi":"前","text":"qián","tone":2}]'::jsonb, 2, '2', 'Steps moving forward — *ahead*, the direction you''re heading. qián ≈ "chyen" rising. Tone 2 goes up, like moving forward and upward.', 'Langkah yang maju ke depan — *depan*, arah yang sedang dituju. qián ≈ "chyen" naik. Nada 2 naik terus, kayak bergerak maju dan ke atas.', null, null, null, array['[object Object]', '[object Object]']::text[], 3, array['direction', 'beginner', 'high_frequency']::text[], true),
