  ('hanzi_jian_meet', '见', '見', 'see / meet', 'bertemu / melihat', array['see / meet']::text[], array['bertemu / melihat']::text[], array[]::text[], array[]::text[], 'jiàn', 'jian4', '[{"hanzi":"见","text":"jiàn","tone":4}]'::jsonb, 4, '4', 'Already learned — an eye finally *seeing*, two people *meeting*. jiàn ≈ "jyen!" Tone 4.', 'Sudah dipelajari — mata yang akhirnya *melihat*, dua orang yang *bertemu*. jiàn ≈ "jyen!" Nada 4.', null, null, null, array['[object Object]', '[object Object]']::text[], 1, array['plans', 'verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_mian_face', '面', '面', 'face / meet part', 'wajah / bagian temu', array['face / meet part']::text[], array['wajah / bagian temu']::text[], array[]::text[], array[]::text[], 'miàn', 'mian4', '[{"hanzi":"面","text":"miàn","tone":4}]'::jsonb, 4, '4', 'Already learned — a flat surface, a *face*. When combined with 见, it means *meeting* face to face. miàn ≈ "myen!" Tone 4.', 'Sudah dipelajari — permukaan datar, sebuah *wajah*. Digabung dengan 见 berarti *bertemu* tatap muka. miàn ≈ "myen!" Nada 4.', null, null, null, array['[object Object]']::text[], 2, array['plans', 'noun_part', 'beginner']::text[], true),
  ('hanzi_yue_appointment', '约', '約', 'make appointment', 'janjian', array['make appointment']::text[], array['janjian']::text[], array[]::text[], array[]::text[], 'yuē', 'yue1', '[{"hanzi":"约","text":"yuē","tone":1}]'::jsonb, 1, '1', 'A thread 纟 tying two people together — *arrange*, making a date or appointment. yuē ≈ "yweh" flat. Tone 1 high and steady like a confirmed plan.', 'Benang 纟 yang mengikat dua orang bersama — *membuat janji*, mengatur pertemuan. yuē ≈ "yweh" flat. Nada 1 tinggi rata kayak rencana yang sudah dikonfirmasi.', null, null, null, array['[object Object]', '[object Object]']::text[], 3, array['plans', 'verb', 'beginner']::text[], true),
  ('hanzi_deng_wait', '等', '等', 'wait', 'tunggu', array['wait']::text[], array['tunggu']::text[], array[]::text[], array[]::text[], 'děng', 'deng3', '[{"hanzi":"等","text":"děng","tone":3}]'::jsonb, 3, '3', 'Equal bamboo tablets 竹 arranged in order — *wait*, everything lined up in sequence. děng ≈ "dung" dipping then rising. Tone 3 like the patience of waiting.', 'Tablet bambu 竹 yang tersusun rapi — *menunggu*, semuanya berbaris berurutan. děng ≈ "dung" turun terus naik. Nada 3 kayak kesabaran menunggu.', null, null, null, array['[object Object]', '[object Object]']::text[], 4, array['plans', 'verb', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_yiqi', '起', '起', 'rise / together part', 'bangun / bagian bersama', array['rise / together part']::text[], array['bangun / bagian bersama']::text[], array[]::text[], array[]::text[], 'qǐ', 'qi3', '[{"hanzi":"起","text":"qǐ","tone":3}]'::jsonb, 3, '3', 'Already learned — *rise*, *start*. In 一起 it means all rising together, doing things *together*. qǐ ≈ "chi" Tone 3.', 'Sudah dipelajari — *bangkit*, *mulai*. Dalam 一起 berarti semuanya bangkit bersama, melakukan sesuatu *bersama*. qǐ ≈ "chi" Nada 3.', null, null, null, array['[object Object]']::text[], 5, array['plans', 'verb_part', 'beginner', 'high_frequency']::text[], true),
  ('hanzi_hou_after', '后', '後', 'after', 'setelah', array['after']::text[], array['setelah']::text[], array[]::text[], array[]::text[], 'hòu', 'hou4', '[{"hanzi":"后","text":"hòu","tone":4}]'::jsonb, 4, '4', 'Already learned — steps slowing, looking *behind*. hòu ≈ "ho!" Tone 4. Used in 以后 meaning *after / later*.', 'Sudah dipelajari — langkah melambat, melihat ke *belakang*. hòu ≈ "ho!" Nada 4. Dipakai dalam 以后 yang berarti *setelah / nanti*.', null, null, null, array['[object Object]']::text[], 6, array['plans', 'time', 'beginner', 'high_frequency']::text[], true)
insert into public.words (external_id, simplified, traditional, meaning_en, meaning_id, accepted_meanings_en, accepted_meanings_id, blocked_meanings_en, blocked_meanings_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_pattern, part_of_speech, mnemonic_en, mnemonic_id, tone_note_en, tone_note_id, usage_note_en, usage_note_id, audio_url, examples, order_index, tags, is_core_word, is_reviewable) values
  ('word_wo', '我', '我', 'I / me', 'aku / saya', array['I / me']::text[], array['aku / saya']::text[], array[]::text[], array[]::text[], 'wǒ', 'wo3', '[{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '3', 'pronoun', 'One character, one meaning — point to your own chest, that''s *me*.', 'Satu karakter, satu makna — nunjuk ke dada sendiri, itulah *aku*.', null, null, null, null, null, array['[object Object]']::text[], 1, array['self']::text[], true, true),
  ('word_ni', '你', '你', 'you', 'kamu', array['you']::text[], array['kamu']::text[], array[]::text[], array[]::text[], 'nǐ', 'ni3', '[{"hanzi":"你","text":"nǐ","tone":3}]'::jsonb, '3', 'pronoun', 'One character, one person — whoever is standing in front of *you* right now.', 'Satu karakter, satu orang — yang berdiri di depan *kamu* sekarang.', null, null, null, null, null, array['[object Object]']::text[], 2, array['self']::text[], true, true),
  ('word_shi', '是', '是', 'to be / is', 'adalah', array['to be / is']::text[], array['adalah']::text[], array[]::text[], array[]::text[], 'shì', 'shi4', '[{"hanzi":"是","text":"shì","tone":4}]'::jsonb, '4', 'verb', '是 is the equals sign of Mandarin — X *is* Y, clear and direct.', '是 adalah kata paling tegas untuk bilang sesuatu *adalah* sesuatu — kayak tanda sama dengan.', null, null, 'Used between subject and noun.', 'Dipakai antara subjek dan kata benda.', null, array['[object Object]']::text[], 3, array['identity']::text[], true, true),
  ('word_you_have', '有', '有', 'have / there is', 'punya / ada', array['have / there is']::text[], array['punya / ada']::text[], array[]::text[], array[]::text[], 'yǒu', 'you3', '[{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '3', 'verb', 'To *have* or to exist — 有 attaches to anything you own or anything that exists.', 'Ada atau *punya* — 有 nempel di depan apapun yang kamu miliki atau yang keberadaannya mau ditegasin.', null, null, 'Can mean "have" or "there is/are".', 'Bisa berarti "punya" atau "ada".', null, array['[object Object]']::text[], 4, array['basic']::text[], true, true),
  ('word_meiyou', '没有', '沒有', 'do not have / there is no', 'tidak punya / tidak ada', array['do not have / there is no']::text[], array['tidak punya / tidak ada']::text[], array[]::text[], array[]::text[], 'méi yǒu', 'mei2 you3', '[{"hanzi":"没","text":"méi","tone":2},{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '2-3', 'verb phrase', '没 + 有 — *don''t have* / *there isn''t*. The direct opposite of 有.', '没 + 有 — *tidak ada*, kebalikan langsung dari 有. Kalau 有 itu "ada", 没有 itu "kosong".', null, null, 'Negation of 有. Use 没有 not 不有.', 'Negasi dari 有. Gunakan 没有, bukan 不有.', null, array['[object Object]']::text[], 5, array['basic', 'negation']::text[], true, true),
  ('word_bu', '不', '不', 'not', 'tidak', array['not']::text[], array['tidak']::text[], array[]::text[], array[]::text[], 'bù', 'bu4', '[{"hanzi":"不","text":"bù","tone":4}]'::jsonb, '4', 'negation', 'Put 不 before any word and it flips to *not* — the most used negation button.', 'Taruh 不 sebelum kata apapun, langsung jadi *tidak* — tombol negatif paling sering dipakai.', null, null, 'Place before verbs or adjectives to negate.', 'Letakkan sebelum kata kerja atau sifat untuk menegasikan.', null, array['[object Object]']::text[], 6, array['negation']::text[], true, true),
  ('word_hao', '好', '好', 'good / okay', 'baik / oke', array['good / okay']::text[], array['baik / oke']::text[], array[]::text[], array[]::text[], 'hǎo', 'hao3', '[{"hanzi":"好","text":"hǎo","tone":3}]'::jsonb, '3', 'adjective', '好 works as an answer, a compliment, or a greeting — all wrapped in one word: *good*.', '好 bisa jadi jawaban, pujian, atau sapaan — semua dalam satu kata *baik*.', null, null, null, null, null, array['[object Object]']::text[], 7, array['basic']::text[], true, true),
  ('word_qu', '去', '去', 'go', 'pergi', array['go']::text[], array['pergi']::text[], array[]::text[], array[]::text[], 'qù', 'qu4', '[{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '4', 'verb', '*Go* — one word, one direction, leaving where you are.', '*Pergi* — satu kata, satu arah, meninggalkan tempat sekarang.', null, null, null, null, null, array['[object Object]']::text[], 1, array['action']::text[], true, true),
  ('word_lai', '来', '來', 'come', 'datang', array['come']::text[], array['datang']::text[], array[]::text[], array[]::text[], 'lái', 'lai2', '[{"hanzi":"来","text":"lái","tone":2}]'::jsonb, '2', 'verb', '*Come* — the opposite of 去, moving toward instead of away.', '*Datang* ke sini — kebalikan dari 去, gerakannya mendekat bukan menjauh.', null, null, null, null, null, array['[object Object]']::text[], 2, array['action']::text[], true, true),
  ('word_kan', '看', '看', 'look / see', 'lihat', array['look / see']::text[], array['lihat']::text[], array[]::text[], array[]::text[], 'kàn', 'kan4', '[{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, '4', 'verb', '*Look* or *watch* — 看 works for watching TV or just glancing over.', '*Lihat* atau *tonton* — 看 bisa buat nonton TV atau sekedar melirik.', null, null, 'Can mean look, watch, or read depending on context.', 'Bisa berarti lihat, tonton, atau baca tergantung konteks.', null, array['[object Object]']::text[], 3, array['action']::text[], true, true),
  ('word_xiang', '想', '想', 'want / think', 'ingin / pikir', array['want / think']::text[], array['ingin / pikir']::text[], array[]::text[], array[]::text[], 'xiǎng', 'xiang3', '[{"hanzi":"想","text":"xiǎng","tone":3}]'::jsonb, '3', 'verb', '*Want* or *miss* — 想 can mean craving something or missing someone.', '*Mau* atau *kangen* — 想 bisa berarti ingin sesuatu atau merindukan seseorang.', null, null, 'Place before another verb to mean "want to".', 'Letakkan sebelum kata kerja lain untuk berarti "mau/ingin".', null, array['[object Object]']::text[], 4, array['action']::text[], true, true),
  ('word_chi', '吃', '吃', 'eat', 'makan', array['eat']::text[], array['makan']::text[], array[]::text[], array[]::text[], 'chī', 'chi1', '[{"hanzi":"吃","text":"chī","tone":1}]'::jsonb, '1', 'verb', '*Eat* — 口 mouth is right there, because it''s all about putting food in.', '*Makan* — 口 mulut ada di sana, karena emang soal masukin makanan.', null, null, null, null, null, array['[object Object]']::text[], 5, array['food']::text[], true, true),
  ('word_he', '喝', '喝', 'drink', 'minum', array['drink']::text[], array['minum']::text[], array[]::text[], array[]::text[], 'hē', 'he1', '[{"hanzi":"喝","text":"hē","tone":1}]'::jsonb, '1', 'verb', '*Drink* — same idea as 吃, 口 mouth, but this time for liquids.', '*Minum* — sama kayak 吃, ada 口 mulut, tapi kali ini untuk cairan.', null, null, null, null, null, array['[object Object]']::text[], 6, array['drink']::text[], true, true),
  ('word_ma', '吗', '嗎', 'question particle', 'partikel tanya', array['question particle']::text[], array['partikel tanya']::text[], array[]::text[], array[]::text[], 'ma', 'ma0', '[{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '0', 'particle', '吗 at the end flips any statement into a question — that simple.', '吗 di ujung kalimat, pernyataan langsung jadi pertanyaan — sesimpel itu.', null, null, 'Always goes at the end of a sentence.', 'Selalu di akhir kalimat.', null, array['[object Object]']::text[], 1, array['question']::text[], true, true),
  ('word_ne', '呢', '呢', 'and you / what about', 'bagaimana dengan', array['and you / what about']::text[], array['bagaimana dengan']::text[], array[]::text[], array[]::text[], 'ne', 'ne0', '[{"hanzi":"呢","text":"ne","tone":0}]'::jsonb, '0', 'particle', '呢 tosses the question back casually — "and *what about you*?"', '呢 kayak nanya balik dengan santai — "terus kamu *gimana*?"', null, null, 'Softer than 吗, used to redirect the question.', 'Lebih ringan dari 吗, dipakai untuk balik bertanya.', null, array['[object Object]']::text[], 2, array['question']::text[], true, true),
  ('word_shei', '谁', '誰', 'who', 'siapa', array['who']::text[], array['siapa']::text[], array[]::text[], array[]::text[], 'shéi', 'shei2', '[{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, '2', 'question word', '*Who* — one word for any question about a person.', '*Siapa* — satu kata untuk semua pertanyaan tentang orang.', null, null, null, null, null, array['[object Object]']::text[], 3, array['question']::text[], true, true),
  ('word_shenme', '什么', '什麼', 'what', 'apa', array['what']::text[], array['apa']::text[], array[]::text[], array[]::text[], 'shén me', 'shen2 me0', '[{"hanzi":"什","text":"shén","tone":2},{"hanzi":"么","text":"me","tone":0}]'::jsonb, '2-0', 'question word', '*What* — 什+么 together, the most common question word in conversation.', '*Apa* — kombinasi 什+么, kata tanya paling sering muncul dalam percakapan.', null, null, null, null, null, array['[object Object]']::text[], 4, array['question']::text[], true, true),
  ('word_nali', '哪里', '哪裡', 'where', 'di mana', array['where']::text[], array['di mana']::text[], array[]::text[], array[]::text[], 'nǎ lǐ', 'na3 li3', '[{"hanzi":"哪","text":"nǎ","tone":3},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '3-3', 'question word', '*Where* — 哪 which + 里 inside, asking about location naturally.', '*Di mana* — 哪 mana + 里 di dalam, nanya lokasi dengan natural.', null, null, null, null, null, array['[object Object]']::text[], 5, array['location']::text[], true, true),
  ('word_dui', '对', '對', 'correct / right', 'benar', array['correct / right']::text[], array['benar']::text[], array[]::text[], array[]::text[], 'duì', 'dui4', '[{"hanzi":"对","text":"duì","tone":4}]'::jsonb, '4', 'adjective', '*Correct* or *right* — works as a short answer or confirmation.', '*Betul* atau *benar* — bisa jadi jawaban singkat atau konfirmasi.', null, null, 'Used to confirm or agree.', 'Dipakai untuk mengkonfirmasi atau setuju.', null, array['[object Object]']::text[], 6, array['question']::text[], true, true),
  ('word_jintian', '今天', '今天', 'today', 'hari ini', array['today']::text[], array['hari ini']::text[], array[]::text[], array[]::text[], 'jīn tiān', 'jin1 tian1', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '1-1', 'time word', '今 now + 天 day — *today*, the day you''re actually living.', '今 sekarang + 天 hari — *hari ini*, bukan kemarin bukan besok.', null, null, 'Always placed before the subject or verb.', 'Selalu diletakkan sebelum subjek atau kata kerja.', null, array['[object Object]']::text[], 1, array['time']::text[], true, true),
  ('word_mingtian', '明天', '明天', 'tomorrow', 'besok', array['tomorrow']::text[], array['besok']::text[], array[]::text[], array[]::text[], 'míng tiān', 'ming2 tian1', '[{"hanzi":"明","text":"míng","tone":2},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '2-1', 'time word', '明 bright + 天 day — *tomorrow*, the bright day still ahead.', '明 terang + 天 hari — *besok*, hari yang masih terang di depan.', null, null, null, null, null, array['[object Object]']::text[], 2, array['time']::text[], true, true),
  ('word_xianzai', '现在', '現在', 'now', 'sekarang', array['now']::text[], array['sekarang']::text[], array[]::text[], array[]::text[], 'xiàn zài', 'xian4 zai4', '[{"hanzi":"现","text":"xiàn","tone":4},{"hanzi":"在","text":"zài","tone":4}]'::jsonb, '4-4', 'time word', '现 appearing + 在 here — *now*, the moment that''s happening.', '现 muncul + 在 di sini — *sekarang* juga, momen yang lagi terjadi.', null, null, null, null, null, array['[object Object]']::text[], 3, array['time']::text[], true, true),
  ('word_meitian', '每天', '每天', 'every day', 'setiap hari', array['every day']::text[], array['setiap hari']::text[], array[]::text[], array[]::text[], 'měi tiān', 'mei3 tian1', '[{"hanzi":"每","text":"měi","tone":3},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '3-1', 'time word', '每 every + 天 day — *every day*, no exceptions.', '每 setiap + 天 hari — *setiap hari*, tanpa kecuali.', null, null, null, null, null, array['[object Object]']::text[], 4, array['time']::text[], true, true),
  ('word_zao', '早', '早', 'early / morning', 'pagi / awal', array['early / morning']::text[], array['pagi / awal']::text[], array[]::text[], array[]::text[], 'zǎo', 'zao3', '[{"hanzi":"早","text":"zǎo","tone":3}]'::jsonb, '3', 'time word', 'The sun barely up, air still fresh — that''s *morning*.', 'Matahari baru sepenggalah, udara masih segar — inilah *pagi*.', null, null, '早 alone can mean "good morning" in casual speech.', '早 sendiri bisa berarti "selamat pagi" dalam percakapan santai.', null, array['[object Object]']::text[], 5, array['time']::text[], true, true),
  ('word_zai_location', '在', '在', 'be at / in', 'berada di', array['be at / in']::text[], array['berada di']::text[], array[]::text[], array[]::text[], 'zài', 'zai4', '[{"hanzi":"在","text":"zài","tone":4}]'::jsonb, '4', 'verb/preposition', '在 marks *where* something is — put it before a location.', '在 menandai *di mana* sesuatu berada — taruh sebelum lokasi, langsung jelas posisinya.', null, null, '在 + location = to be at a place.', '在 + lokasi = berada di suatu tempat.', null, array['[object Object]']::text[], 1, array['location']::text[], true, true),
  ('word_zheli', '这里', '這裡', 'here', 'di sini', array['here']::text[], array['di sini']::text[], array[]::text[], array[]::text[], 'zhè lǐ', 'zhe4 li3', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '4-3', 'location word', '这 this + 里 inside — *here*, close to where you''re standing.', '这 ini + 里 dalam — *di sini*, lokasi yang dekat dengan pembicara.', null, null, null, null, null, array['[object Object]']::text[], 2, array['location']::text[], true, true),
  ('word_nali_there', '那里', '那裡', 'there', 'di sana', array['there']::text[], array['di sana']::text[], array[]::text[], array[]::text[], 'nà lǐ', 'na4 li3', '[{"hanzi":"那","text":"nà","tone":4},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '4-3', 'location word', '那 that + 里 inside — *there*, further away from you.', '那 itu + 里 dalam — *di sana*, lokasi yang lebih jauh.', null, null, null, null, null, array['[object Object]']::text[], 3, array['location']::text[], true, true),
  ('word_jia', '家', '家', 'home', 'rumah', array['home']::text[], array['rumah']::text[], array[]::text[], array[]::text[], 'jiā', 'jia1', '[{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '1', 'noun', 'One word for everything that feels like *home* — the place you return to.', 'Satu kata untuk semua yang terasa kayak *rumah* — tempat pulang.', null, null, null, null, null, array['[object Object]']::text[], 4, array['location']::text[], true, true),
  ('word_xuexiao', '学校', '學校', 'school', 'sekolah', array['school']::text[], array['sekolah']::text[], array[]::text[], array[]::text[], 'xué xiào', 'xue2 xiao4', '[{"hanzi":"学","text":"xué","tone":2},{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, '2-4', 'noun', '学 study + 校 school — *school*, the official place for learning.', '学 belajar + 校 sekolah — *sekolah*, tempat belajar yang resmi.', null, null, null, null, null, array['[object Object]']::text[], 5, array['location']::text[], true, true),
  ('word_huijia', '回家', '回家', 'go home', 'pulang', array['go home']::text[], array['pulang']::text[], array[]::text[], array[]::text[], 'huí jiā', 'hui2 jia1', '[{"hanzi":"回","text":"huí","tone":2},{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '2-1', 'verb phrase', '回 return + 家 home — *go home*, the trip everyone looks forward to.', '回 kembali + 家 rumah — *pulang*, perjalanan yang selalu ditunggu.', null, null, null, null, null, array['[object Object]']::text[], 6, array['movement']::text[], true, true),
  ('word_mai_buy', '买', '買', 'buy', 'beli', array['buy']::text[], array['beli']::text[], array[]::text[], array[]::text[], 'mǎi', 'mai3', '[{"hanzi":"买","text":"mǎi","tone":3}]'::jsonb, '3', 'verb', '*Buy* — the action of pulling out your wallet and getting something.', '*Beli* — aksi nurunin dompet dan nuker barang.', null, null, null, null, null, array['[object Object]']::text[], 1, array['shopping']::text[], true, true),
  ('word_qian', '钱', '錢', 'money', 'uang', array['money']::text[], array['uang']::text[], array[]::text[], array[]::text[], 'qián', 'qian2', '[{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '2', 'noun', '*Money* — always moving, always needed.', '*Uang* — selalu berpindah tangan, selalu dicari.', null, null, null, null, null, array['[object Object]']::text[], 2, array['shopping']::text[], true, true),
  ('word_duoshao', '多少', '多少', 'how much / how many', 'berapa', array['how much / how many']::text[], array['berapa']::text[], array[]::text[], array[]::text[], 'duō shǎo', 'duo1 shao3', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, '1-3', 'question word', '多 much + 少 little — *how much / how many*, asking the amount between the two.', '多 banyak + 少 sedikit — *berapa*, nanya jumlah di antara banyak dan sedikit.', null, null, null, null, null, array['[object Object]']::text[], 3, array['shopping']::text[], true, true),
