  ('word_liang_ge', '两个', '兩個', 'two items / two people', 'dua buah / dua orang', array['two items / two people']::text[], array['dua buah / dua orang']::text[], array[]::text[], array[]::text[], 'liǎng ge', 'liang3 ge0', '[{"hanzi":"两","text":"liǎng","tone":3},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '3-0', 'measure phrase', '两 two (for counting) + 个 — *two* of something. Use 两 not 二 before measure words.', '两 dua (untuk menghitung) + 个 — *dua* buah sesuatu. Pakai 两 bukan 二 sebelum kata bantu bilangan.', null, null, 'Use 两 (liǎng) not 二 when counting with measure words.', 'Gunakan 两 (liǎng) bukan 二 saat menghitung dengan kata bantu bilangan.', null, array['[object Object]']::text[], 3, array['measure']::text[], true, true),
