  ('word_xiayu', '下雨', '下雨', 'rain / raining', 'hujan', array['rain / raining']::text[], array['hujan']::text[], array[]::text[], array[]::text[], 'xià yǔ', 'xia4 yu3', '[{"hanzi":"下","text":"xià","tone":4},{"hanzi":"雨","text":"yǔ","tone":3}]'::jsonb, '4-3', 'verb', '下 fall + 雨 rain — *to rain*, rain falling down.', '下 turun + 雨 hujan — *hujan*, hujan yang jatuh ke bawah.', null, null, '下雨 = raining. 下雪 = snowing. Same pattern with 下.', '下雨 = hujan. 下雪 = salju. Pola 下 yang sama.', null, array['[object Object]']::text[], 2, array['weather']::text[], true, true),
