  ('word_re_weather', '热', '熱', 'hot', 'panas', array['hot']::text[], array['panas']::text[], array[]::text[], array[]::text[], 'rè', 're4', '[{"hanzi":"热","text":"rè","tone":4}]'::jsonb, '4', 'adjective', 'Already learned — *hot*. Used for weather too.', 'Sudah dipelajari — *panas*. Juga dipakai untuk cuaca.', null, null, null, null, null, array['[object Object]']::text[], 5, array['weather']::text[], true, true),
