  ('word_yifu', '衣服', '衣服', 'clothes', 'pakaian', array['clothes']::text[], array['pakaian']::text[], array[]::text[], array[]::text[], 'yī fu', 'yi1 fu0', '[{"hanzi":"衣","text":"yī","tone":1},{"hanzi":"服","text":"fu","tone":0}]'::jsonb, '1-0', 'noun', '衣 garment + 服 serve — *clothes*, what serves and covers your body.', '衣 pakaian + 服 melayani — *baju*, yang melayani dan menutupi tubuhmu.', null, null, null, null, null, array['[object Object]']::text[], 1, array['clothes']::text[], true, true),
