  ('word_xuexiao_place', '学校', '學校', 'school', 'sekolah', array['school']::text[], array['sekolah']::text[], array[]::text[], array[]::text[], 'xué xiào', 'xue2 xiao4', '[{"hanzi":"学","text":"xué","tone":2},{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, '2-4', 'noun', 'Already learned — 学 study + 校 school. *School*.', 'Sudah dipelajari — 学 belajar + 校 sekolah. *Sekolah*.', null, null, null, null, null, array['[object Object]']::text[], 5, array['places']::text[], true, true),
  ('word_jichang', '机场', '機場', 'airport', 'bandara', array['airport']::text[], array['bandara']::text[], array[]::text[], array[]::text[], 'jī chǎng', 'ji1 chang3', '[{"hanzi":"机","text":"jī","tone":1},{"hanzi":"场","text":"chǎng","tone":3}]'::jsonb, '1-3', 'noun', '机 machine/plane + 场 field — *airport*, the field for planes.', '机 mesin/pesawat + 场 lapangan — *bandara*, lapangan untuk pesawat.', null, null, null, null, null, array['[object Object]']::text[], 6, array['places']::text[], true, true),
  ('word_diancai', '点菜', '點菜', 'order food', 'pesan makanan', array['order food']::text[], array['pesan makanan']::text[], array[]::text[], array[]::text[], 'diǎn cài', 'dian3 cai4', '[{"hanzi":"点","text":"diǎn","tone":3},{"hanzi":"菜","text":"cài","tone":4}]'::jsonb, '3-4', 'verb', '点 point + 菜 dish — *order food*, pointing at what you want.', '点 tunjuk + 菜 hidangan — *pesan makanan*, menunjuk apa yang kamu mau.', null, null, null, null, null, array['[object Object]']::text[], 1, array['restaurant']::text[], true, true),
  ('word_caidan', '菜单', '菜單', 'menu', 'menu', array['menu']::text[], array['menu']::text[], array[]::text[], array[]::text[], 'cài dān', 'cai4 dan1', '[{"hanzi":"菜","text":"cài","tone":4},{"hanzi":"单","text":"dān","tone":1}]'::jsonb, '4-1', 'noun', '菜 dishes + 单 list — *menu*, the list of dishes.', '菜 hidangan + 单 daftar — *menu*, daftar hidangan.', null, null, null, null, null, array['[object Object]']::text[], 2, array['restaurant']::text[], true, true),
  ('word_jidan', '鸡蛋', '雞蛋', 'egg', 'telur', array['egg']::text[], array['telur']::text[], array[]::text[], array[]::text[], 'jī dàn', 'ji1 dan4', '[{"hanzi":"鸡","text":"jī","tone":1},{"hanzi":"蛋","text":"dàn","tone":4}]'::jsonb, '1-4', 'noun', '鸡 chicken + 蛋 egg — *egg*, literally "chicken egg".', '鸡 ayam + 蛋 telur — *telur*, harfiahnya "telur ayam".', null, null, null, null, null, array['[object Object]']::text[], 3, array['restaurant']::text[], true, true),
  ('word_tang', '汤', '湯', 'soup', 'sup', array['soup']::text[], array['sup']::text[], array[]::text[], array[]::text[], 'tāng', 'tang1', '[{"hanzi":"汤","text":"tāng","tone":1}]'::jsonb, '1', 'noun', '*Soup* — warm, liquid, comforting.', '*Sup* — hangat, cair, menghibur.', null, null, null, null, null, array['[object Object]']::text[], 4, array['restaurant']::text[], true, true),
  ('word_kuai_yidian', '快一点', '快一點', 'a bit faster', 'sedikit lebih cepat', array['a bit faster']::text[], array['sedikit lebih cepat']::text[], array[]::text[], array[]::text[], 'kuài yì diǎn', 'kuai4 yi4 dian3', '[{"hanzi":"快","text":"kuài","tone":4},{"hanzi":"一","text":"yì","tone":4},{"hanzi":"点","text":"diǎn","tone":3}]'::jsonb, '4-4-3', 'phrase', '快 fast + 一 one + 点 bit — *a bit faster*, nudging speed up slightly.', '快 cepat + 一 satu + 点 sedikit — *sedikit lebih cepat*, mendorong kecepatan sedikit.', null, null, '一点 after adjective = a little more. 慢一点 = a bit slower, 大一点 = a bit bigger.', '一点 setelah kata sifat = sedikit lebih. 慢一点 = sedikit lebih lambat, 大一点 = sedikit lebih besar.', null, array['[object Object]']::text[], 5, array['restaurant']::text[], true, true),
  ('word_mantou', '馒头', '饅頭', 'steamed bun', 'mantou / roti kukus', array['steamed bun']::text[], array['mantou / roti kukus']::text[], array[]::text[], array[]::text[], 'mán tou', 'man2 tou0', '[{"hanzi":"馒","text":"mán","tone":2},{"hanzi":"头","text":"tou","tone":0}]'::jsonb, '2-0', 'noun', 'A fluffy rounded bun — *steamed bun*, the classic Chinese bread.', 'Roti bulat yang lembut — *mantou*, roti kukus China yang klasik.', null, null, null, null, null, array['[object Object]']::text[], 6, array['restaurant']::text[], true, true),
  ('word_mai_sell', '卖', '賣', 'sell', 'jual', array['sell']::text[], array['jual']::text[], array[]::text[], array[]::text[], 'mài', 'mai4', '[{"hanzi":"卖","text":"mài","tone":4}]'::jsonb, '4', 'verb', '*Sell* — the shopkeeper''s side of the transaction.', '*Jual* — sisi penjual dalam transaksi.', null, null, '卖 sell vs 买 buy — mirror characters with opposite meanings.', '卖 jual vs 买 beli — karakter cerminan dengan arti berlawanan.', null, array['[object Object]']::text[], 1, array['shop']::text[], true, true),
  ('word_jiage', '价格', '價格', 'price', 'harga', array['price']::text[], array['harga']::text[], array[]::text[], array[]::text[], 'jià gé', 'jia4 ge2', '[{"hanzi":"价","text":"jià","tone":4},{"hanzi":"格","text":"gé","tone":2}]'::jsonb, '4-2', 'noun', '价 price + 格 standard — *price*, the official stated amount.', '价 harga + 格 standar — *harga*, jumlah resmi yang dinyatakan.', null, null, null, null, null, array['[object Object]']::text[], 2, array['shop']::text[], true, true),
  ('word_yuan', '元', '元', 'yuan / dollar', 'yuan / dolar', array['yuan / dollar']::text[], array['yuan / dolar']::text[], array[]::text[], array[]::text[], 'yuán', 'yuan2', '[{"hanzi":"元","text":"yuán","tone":2}]'::jsonb, '2', 'measure', '*Yuan* — the formal written unit of Chinese currency.', '*Yuan* — satuan mata uang China yang formal dalam tulisan.', null, null, '元 is formal/written. 块 is spoken. Both mean yuan.', '元 adalah formal/tulisan. 块 adalah lisan. Keduanya berarti yuan.', null, array['[object Object]']::text[], 3, array['shop']::text[], true, true),
  ('word_shuaka', '刷卡', '刷卡', 'pay by card', 'bayar pakai kartu', array['pay by card']::text[], array['bayar pakai kartu']::text[], array[]::text[], array[]::text[], 'shuā kǎ', 'shua1 ka3', '[{"hanzi":"刷","text":"shuā","tone":1},{"hanzi":"卡","text":"kǎ","tone":3}]'::jsonb, '1-3', 'verb phrase', '刷 swipe + 卡 card — *pay by card*, swiping a card.', '刷 gesek + 卡 kartu — *bayar pakai kartu*, menggesek kartu.', null, null, null, null, null, array['[object Object]']::text[], 4, array['shop']::text[], true, true),
  ('word_fuqian', '付钱', '付錢', 'pay money', 'bayar', array['pay money']::text[], array['bayar']::text[], array[]::text[], array[]::text[], 'fù qián', 'fu4 qian2', '[{"hanzi":"付","text":"fù","tone":4},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '4-2', 'verb phrase', '付 pay + 钱 money — *pay money*, the act of paying.', '付 bayar + 钱 uang — *bayar*, tindakan membayar.', null, null, null, null, null, array['[object Object]']::text[], 5, array['shop']::text[], true, true),
  ('word_keyi_shuaka_ma', '可以刷卡吗', '可以刷卡嗎', 'can I pay by card?', 'bisa bayar pakai kartu?', array['can I pay by card?']::text[], array['bisa bayar pakai kartu?']::text[], array[]::text[], array[]::text[], 'kě yǐ shuā kǎ ma', 'ke3 yi3 shua1 ka3 ma0', '[{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3},{"hanzi":"刷","text":"shuā","tone":1},{"hanzi":"卡","text":"kǎ","tone":3},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-3-1-3-0', 'question phrase', '可以 can + 刷卡 pay by card + 吗 question — *Can I pay by card?* — essential phrase at any shop.', '可以 bisa + 刷卡 bayar kartu + 吗 tanya — *Bisa bayar pakai kartu?* — frasa penting di toko manapun.', null, null, null, null, null, array['[object Object]']::text[], 6, array['shop']::text[], true, true),
  ('word_bangzhu', '帮助', '幫助', 'help', 'bantuan / membantu', array['help']::text[], array['bantuan / membantu']::text[], array[]::text[], array[]::text[], 'bāng zhù', 'bang1 zhu4', '[{"hanzi":"帮","text":"bāng","tone":1},{"hanzi":"助","text":"zhù","tone":4}]'::jsonb, '1-4', 'noun/verb', '帮 help + 助 assist — *help*, two characters reinforcing the same meaning.', '帮 bantu + 助 membantu — *bantuan*, dua karakter yang memperkuat makna yang sama.', null, null, '帮助 is the noun (help) and verb (to help).', '帮助 adalah kata benda (bantuan) dan kata kerja (membantu).', null, array['[object Object]']::text[], 1, array['help']::text[], true, true),
  ('word_bang_wo', '帮我', '幫我', 'help me', 'bantu saya', array['help me']::text[], array['bantu saya']::text[], array[]::text[], array[]::text[], 'bāng wǒ', 'bang1 wo3', '[{"hanzi":"帮","text":"bāng","tone":1},{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '1-3', 'phrase', '帮 help + 我 me — *help me*, the most direct request.', '帮 bantu + 我 aku — *bantu aku*, permintaan paling langsung.', null, null, null, null, null, array['[object Object]']::text[], 2, array['help']::text[], true, true),
  ('word_budong', '不懂', '不懂', 'do not understand', 'tidak mengerti', array['do not understand']::text[], array['tidak mengerti']::text[], array[]::text[], array[]::text[], 'bù dǒng', 'bu4 dong3', '[{"hanzi":"不","text":"bù","tone":4},{"hanzi":"懂","text":"dǒng","tone":3}]'::jsonb, '4-3', 'phrase', '不 not + 懂 understand — *don''t understand*, the honest admission.', '不 tidak + 懂 mengerti — *tidak mengerti*, pengakuan yang jujur.', null, null, null, null, null, array['[object Object]']::text[], 3, array['help']::text[], true, true),
  ('word_zaishuo', '再说', '再說', 'say again', 'bilang lagi', array['say again']::text[], array['bilang lagi']::text[], array[]::text[], array[]::text[], 'zài shuō', 'zai4 shuo1', '[{"hanzi":"再","text":"zài","tone":4},{"hanzi":"说","text":"shuō","tone":1}]'::jsonb, '4-1', 'verb phrase', '再 again + 说 say — *say again*, repeat what was just said.', '再 lagi + 说 bilang — *ulangi*, ulangi apa yang baru saja dikatakan.', null, null, null, null, null, array['[object Object]']::text[], 4, array['help']::text[], true, true),
  ('word_mandian', '慢点', '慢點', 'slower', 'pelan sedikit', array['slower']::text[], array['pelan sedikit']::text[], array[]::text[], array[]::text[], 'màn diǎn', 'man4 dian3', '[{"hanzi":"慢","text":"màn","tone":4},{"hanzi":"点","text":"diǎn","tone":3}]'::jsonb, '4-3', 'phrase', '慢 slow + 点 a bit — *a bit slower*, asking someone to slow down.', '慢 lambat + 点 sedikit — *sedikit lebih lambat*, meminta seseorang untuk melambat.', null, null, null, null, null, array['[object Object]']::text[], 5, array['help']::text[], true, true),
  ('word_qingwen', '请问', '請問', 'excuse me / may I ask', 'permisi / mau tanya', array['excuse me / may I ask']::text[], array['permisi / mau tanya']::text[], array[]::text[], array[]::text[], 'qǐng wèn', 'qing3 wen4', '[{"hanzi":"请","text":"qǐng","tone":3},{"hanzi":"问","text":"wèn","tone":4}]'::jsonb, '3-4', 'polite phrase', '请 please + 问 ask — *excuse me / may I ask*, the polite opener before any question.', '请 tolong + 问 tanya — *permisi / boleh tanya*, pembuka sopan sebelum pertanyaan apapun.', null, null, '请问 at the start softens any question — use it when asking strangers.', '请问 di awal melembutkan pertanyaan apapun — gunakan saat bertanya pada orang asing.', null, array['[object Object]']::text[], 6, array['help']::text[], true, true),
  ('word_jianmian', '见面', '見面', 'meet', 'bertemu', array['meet']::text[], array['bertemu']::text[], array[]::text[], array[]::text[], 'jiàn miàn', 'jian4 mian4', '[{"hanzi":"见","text":"jiàn","tone":4},{"hanzi":"面","text":"miàn","tone":4}]'::jsonb, '4-4', 'verb', '见 see + 面 face — *meet*, seeing each other face to face.', '见 lihat + 面 wajah — *bertemu*, melihat satu sama lain bertatap muka.', null, null, null, null, null, array['[object Object]']::text[], 1, array['plans']::text[], true, true),
  ('word_yue', '约', '約', 'make plans / invite', 'janjian / ajak', array['make plans / invite']::text[], array['janjian / ajak']::text[], array[]::text[], array[]::text[], 'yuē', 'yue1', '[{"hanzi":"约","text":"yuē","tone":1}]'::jsonb, '1', 'verb', '*Make plans / invite* — setting up a time to meet someone.', '*Buat janji / ajak* — mengatur waktu untuk bertemu seseorang.', null, null, null, null, null, array['[object Object]']::text[], 2, array['plans']::text[], true, true),
  ('word_deng', '等', '等', 'wait', 'tunggu', array['wait']::text[], array['tunggu']::text[], array[]::text[], array[]::text[], 'děng', 'deng3', '[{"hanzi":"等","text":"děng","tone":3}]'::jsonb, '3', 'verb', '*Wait* — staying in place until someone arrives.', '*Tunggu* — tetap di tempat sampai seseorang datang.', null, null, '等一下 = wait a moment. 等我 = wait for me.', '等一下 = tunggu sebentar. 等我 = tunggu aku.', null, array['[object Object]']::text[], 3, array['plans']::text[], true, true),
  ('word_yiqi', '一起', '一起', 'together', 'bersama', array['together']::text[], array['bersama']::text[], array[]::text[], array[]::text[], 'yì qǐ', 'yi4 qi3', '[{"hanzi":"一","text":"yì","tone":4},{"hanzi":"起","text":"qǐ","tone":3}]'::jsonb, '4-3', 'adverb', '一 one + 起 rise — *together*, one group rising as one.', '一 satu + 起 bangkit — *bersama*, satu kelompok yang bangkit sebagai satu.', null, null, null, null, null, array['[object Object]']::text[], 4, array['plans']::text[], true, true),
  ('word_yihou', '以后', '以後', 'later / after', 'nanti / setelah', array['later / after']::text[], array['nanti / setelah']::text[], array[]::text[], array[]::text[], 'yǐ hòu', 'yi3 hou4', '[{"hanzi":"以","text":"yǐ","tone":3},{"hanzi":"后","text":"hòu","tone":4}]'::jsonb, '3-4', 'time word', '以 using / after + 后 behind — *later / after*, time that comes after now.', '以 setelah + 后 belakang — *nanti / setelah*, waktu yang datang setelah sekarang.', null, null, '以后 = after / later (future). 以前 = before (past).', '以后 = setelah / nanti (masa depan). 以前 = sebelum (masa lalu).', null, array['[object Object]']::text[], 5, array['plans']::text[], true, true),
  ('word_jihua', '计划', '計劃', 'plan', 'rencana', array['plan']::text[], array['rencana']::text[], array[]::text[], array[]::text[], 'jì huà', 'ji4 hua4', '[{"hanzi":"计","text":"jì","tone":4},{"hanzi":"划","text":"huà","tone":4}]'::jsonb, '4-4', 'noun/verb', '计 calculate + 划 draw/plan — *plan*, calculated and drawn out in advance.', '计 hitung + 划 rencana — *rencana*, dihitung dan dirancang sebelumnya.', null, null, null, null, null, array['[object Object]']::text[], 6, array['plans']::text[], true, true)
insert into public.patterns (external_id, title_en, title_id, meaning_en, meaning_id, structure, explanation_en, explanation_id, examples, order_index, tags, is_reviewable) values
  ('pattern_a_shi_b', 'A 是 B', 'A 是 B', 'A is B', 'A adalah B', 'Subject + 是 + noun', 'Use 是 to say identity or category.', 'Gunakan 是 untuk identitas atau kategori.', '[{"simplified":"我是你。","traditional":"我是你。","pinyin":"Wǒ shì nǐ.","meaning":"I am you.","meaning_id":"Aku adalah kamu."}]'::jsonb, 1, array['identity', 'beginner']::text[], false),
  ('pattern_subject_verb', 'Subject + verb', 'Subjek + kata kerja', 'simple action sentence', 'kalimat aksi sederhana', 'Subject + verb', 'Mandarin can make simple action sentences without am/is/are.', 'Mandarin bisa membuat kalimat aksi sederhana tanpa am/is/are.', '[{"simplified":"我去。","traditional":"我去。","pinyin":"Wǒ qù.","meaning":"I go.","meaning_id":"Aku pergi."},{"simplified":"你来。","traditional":"你来。","pinyin":"Nǐ lái.","meaning":"You come.","meaning_id":"Kamu datang."}]'::jsonb, 1, array['sentence_structure', 'beginner']::text[], false),
  ('pattern_yes_no_ma', 'Statement + 吗?', 'Pernyataan + 吗?', 'yes/no question', 'pertanyaan ya/tidak', 'Statement + 吗?', 'Add 吗 to make a yes/no question.', 'Tambahkan 吗 untuk membuat pertanyaan ya/tidak.', '[{"simplified":"你好吗？","traditional":"你好嗎？","pinyin":"Nǐ hǎo ma?","meaning":"How are you?","meaning_id":"Apa kabar?"},{"simplified":"你去吗？","traditional":"你去嗎？","pinyin":"Nǐ qù ma?","meaning":"Are you going?","meaning_id":"Kamu pergi?"}]'::jsonb, 1, array['question', 'beginner']::text[], false),
  ('pattern_time_first', 'Time + action', 'Waktu + aksi', 'time before action', 'waktu sebelum aksi', 'Time + subject + verb', 'Put simple time words before the action.', 'Letakkan kata waktu sederhana sebelum aksi.', '[{"simplified":"今天我去。","traditional":"今天我去。","pinyin":"Jīn tiān wǒ qù.","meaning":"Today I go.","meaning_id":"Hari ini aku pergi."},{"simplified":"明天你来吗？","traditional":"明天你来吗？","pinyin":"Míng tiān nǐ lái ma?","meaning":"Are you coming tomorrow?","meaning_id":"Besok kamu datang?"}]'::jsonb, 1, array['sentence_structure', 'time', 'beginner']::text[], false),
  ('pattern_location_zai', '在 + location', '在 + lokasi', 'being at a place', 'berada di suatu tempat', 'Subject + 在 + place', 'Use 在 to say where someone or something is.', 'Gunakan 在 untuk menyatakan lokasi.', '[{"simplified":"我在家。","traditional":"我在家。","pinyin":"Wǒ zài jiā.","meaning":"I am at home.","meaning_id":"Aku di rumah."},{"simplified":"你在哪里？","traditional":"你在哪裡？","pinyin":"Nǐ zài nǎ lǐ?","meaning":"Where are you?","meaning_id":"Kamu di mana?"}]'::jsonb, 1, array['location', 'beginner']::text[], false),
  ('pattern_duoshaoqian', '多少钱?', '多少钱?', 'asking price', 'bertanya harga', 'Item + 多少钱?', 'Use 多少钱 to ask how much something costs.', 'Gunakan 多少钱 untuk bertanya harga.', '[{"simplified":"多少钱？","traditional":"多少錢？","pinyin":"Duō shao qián?","meaning":"How much?","meaning_id":"Berapa harganya?"},{"simplified":"这多少钱？","traditional":"這多少錢？","pinyin":"Zhè duō shao qián?","meaning":"How much is this?","meaning_id":"Ini berapa?"}]'::jsonb, 1, array['shopping', 'question', 'beginner']::text[], false),
  ('pattern_de_possession', '的 for possession', '的 untuk kepemilikan', 'possession', 'kepemilikan', 'Person + 的 + noun', 'Use 的 to connect a person with something they have or relate to.', 'Gunakan 的 untuk menghubungkan orang dengan sesuatu yang dimiliki/terkait.', '[{"simplified":"我朋友。","traditional":"我朋友。","pinyin":"Wǒ péng you.","meaning":"My friend.","meaning_id":"Temanku."},{"simplified":"你妈妈在家吗？","traditional":"你媽媽在家嗎？","pinyin":"Nǐ mā ma zài jiā ma?","meaning":"Is your mom at home?","meaning_id":"Mama kamu di rumah?"}]'::jsonb, 1, array['possession', 'people', 'beginner']::text[], false),
  ('pattern_hen_adjective', '很 + adjective', '很 + kata sifat', 'describing with adjectives', 'mendeskripsikan dengan kata sifat', 'Subject + 很 + adjective', 'Use 很 before many simple adjectives.', 'Gunakan 很 sebelum banyak kata sifat sederhana.', '[{"simplified":"今天很热。","traditional":"今天很熱。","pinyin":"Jīn tiān hěn rè.","meaning":"Today is very hot.","meaning_id":"Hari ini sangat panas."},{"simplified":"这很贵。","traditional":"這很貴。","pinyin":"Zhè hěn guì.","meaning":"This is very expensive.","meaning_id":"Ini sangat mahal."}]'::jsonb, 1, array['description', 'beginner']::text[], false),
  ('pattern_like_object', '喜欢 + object', '喜欢 + objek', 'saying likes', 'menyatakan suka', 'Subject + 喜欢 + thing/action', 'Use 喜欢 to say what you like.', 'Gunakan 喜欢 untuk mengatakan yang kamu suka.', '[{"simplified":"我喜欢水。","traditional":"我喜歡水。","pinyin":"Wǒ xǐ huān shuǐ.","meaning":"I like water.","meaning_id":"Aku suka air."},{"simplified":"我喜欢吃饭。","traditional":"我喜歡吃飯。","pinyin":"Wǒ xǐ huān chī fàn.","meaning":"I like eating.","meaning_id":"Aku suka makan."}]'::jsonb, 1, array['opinion', 'beginner']::text[], false),
  ('pattern_counting_0_10', 'Numbers 0–10', 'Angka 0–10', 'basic counting', 'menghitung dasar', '零，一，二，三...', 'Use these for basic counting and small quantities.', 'Gunakan ini untuk menghitung dan jumlah kecil.', '[{"simplified":"一个。","traditional":"一個。","pinyin":"Yí ge.","meaning":"One item.","meaning_id":"Satu buah."},{"simplified":"五个。","traditional":"五個。","pinyin":"Wǔ ge.","meaning":"Five items.","meaning_id":"Lima buah."}]'::jsonb, 1, array['number', 'measure_word', 'beginner']::text[], false),
  ('pattern_tens', 'Tens with 十', 'Puluhan dengan 十', 'building 11–99', 'membentuk 11–99', '十 + number / number + 十', 'Combine 十 with numbers to build 11–99.', 'Gabungkan 十 dengan angka untuk membentuk 11–99.', '[{"simplified":"二十个。","traditional":"二十個。","pinyin":"Èr shí ge.","meaning":"Twenty items.","meaning_id":"Dua puluh buah."},{"simplified":"三十块。","traditional":"三十塊。","pinyin":"Sān shí kuài.","meaning":"Thirty yuan.","meaning_id":"Tiga puluh yuan."}]'::jsonb, 1, array['number', 'beginner']::text[], false),
  ('pattern_date_time_words', 'Time words', 'Kata waktu', 'using days and months', 'memakai hari dan bulan', 'Time word + sentence', 'Put time words before or after the subject depending on emphasis.', 'Letakkan kata waktu sebelum atau sesudah subjek sesuai penekanan.', '[{"simplified":"昨天我去。","traditional":"昨天我去。","pinyin":"Zuó tiān wǒ qù.","meaning":"Yesterday I went.","meaning_id":"Kemarin aku pergi."},{"simplified":"星期一你来吗？","traditional":"星期一你來嗎？","pinyin":"Xīng qī yī nǐ lái ma?","meaning":"Are you coming Monday?","meaning_id":"Senin kamu datang?"}]'::jsonb, 1, array['time', 'beginner']::text[], false),
  ('pattern_number_measure_noun', 'Number + measure + noun', 'Angka + kata bantu + benda', 'basic measure words', 'kata bantu hitung dasar', 'Number + measure word + noun', 'Mandarin often needs a measure word between a number and a noun.', 'Mandarin sering membutuhkan kata bantu hitung antara angka dan benda.', '[{"simplified":"一个人。","traditional":"一個人。","pinyin":"Yí ge rén.","meaning":"One person.","meaning_id":"Satu orang."},{"simplified":"一杯水。","traditional":"一杯水。","pinyin":"Yì bēi shuǐ.","meaning":"One cup of water.","meaning_id":"Satu cangkir air."}]'::jsonb, 1, array['measure_word', 'beginner']::text[], false),
  ('pattern_this_that', '这 / 那 / 哪', '这 / 那 / 哪', 'this, that, which', 'ini, itu, yang mana', '这/那/哪 + measure word', 'Use 这, 那, and 哪 with measure words to point or ask which.', 'Gunakan 这, 那, dan 哪 dengan kata bantu untuk menunjuk atau bertanya yang mana.', '[{"simplified":"这个多少钱？","traditional":"這個多少錢？","pinyin":"Zhè ge duō shao qián?","meaning":"How much is this?","meaning_id":"Ini berapa?"},{"simplified":"那个好吗？","traditional":"那個好嗎？","pinyin":"Nà ge hǎo ma?","meaning":"Is that one good?","meaning_id":"Yang itu bagus?"}]'::jsonb, 1, array['demonstrative', 'beginner']::text[], false),
  ('pattern_food_preference', 'Food + 好吃', 'Makanan + 好吃', 'saying food is tasty', 'mengatakan makanan enak', 'Food + 很/不 + 好吃', 'Use 好吃 to describe food as tasty.', 'Gunakan 好吃 untuk menyebut makanan enak.', '[{"simplified":"米饭很好吃。","traditional":"米飯很好吃。","pinyin":"Mǐ fàn hěn hǎo chī.","meaning":"Rice is very tasty.","meaning_id":"Nasi enak banget."},{"simplified":"鸡肉好吃吗？","traditional":"雞肉好吃嗎？","pinyin":"Jī ròu hǎo chī ma?","meaning":"Is chicken tasty?","meaning_id":"Ayam enak?"}]'::jsonb, 1, array['food', 'description', 'beginner']::text[], false),
  ('pattern_ordering_qing', '请 + request', '请 + permintaan', 'polite ordering', 'memesan dengan sopan', '请 + item/action', 'Use 请 to make a request sound polite.', 'Gunakan 请 agar permintaan terdengar sopan.', '[{"simplified":"请一杯茶。","traditional":"請一杯茶。","pinyin":"Qǐng yì bēi chá.","meaning":"A cup of tea, please.","meaning_id":"Tolong satu cangkir teh."},{"simplified":"我要咖啡，冰的。","traditional":"我要咖啡，冰的。","pinyin":"Wǒ yào kā fēi, bīng de.","meaning":"I want coffee, iced.","meaning_id":"Aku mau kopi, yang dingin."}]'::jsonb, 1, array['ordering', 'drink', 'beginner']::text[], false),
  ('pattern_transport_take', '坐 + transport', '坐 + transportasi', 'taking transport', 'naik transportasi', '坐 + transport', 'Use 坐 with transport to say you take a bus, subway, or taxi.', 'Gunakan 坐 dengan transportasi untuk bilang naik bus, metro, atau taksi.', '[{"simplified":"我坐公交车。","traditional":"我坐公交車。","pinyin":"Wǒ zuò gōng jiāo chē.","meaning":"I take the bus.","meaning_id":"Aku naik bus."},{"simplified":"你坐地铁吗？","traditional":"你坐地鐵嗎？","pinyin":"Nǐ zuò dì tiě ma?","meaning":"Do you take the subway?","meaning_id":"Kamu naik subway?"}]'::jsonb, 1, array['transport', 'beginner']::text[], false),
  ('pattern_direction_commands', 'Direction commands', 'Perintah arah', 'simple directions', 'arah sederhana', '一直走 / 左转 / 右转', 'Use direction words with 走 and 转 for basic directions.', 'Gunakan kata arah dengan 走 dan 转 untuk petunjuk jalan dasar.', '[{"simplified":"一直走。","traditional":"一直走。","pinyin":"Yì zhí zǒu.","meaning":"Go straight.","meaning_id":"Jalan lurus."},{"simplified":"左边转。","traditional":"左邊轉。","pinyin":"Zuǒ biān zhuǎn.","meaning":"Turn left.","meaning_id":"Belok kiri."}]'::jsonb, 1, array['direction', 'beginner']::text[], false),
  ('pattern_completed_le', 'Verb + 了', 'Kata kerja + 了', 'completed action', 'aksi selesai', 'Verb + 了', 'Use 了 after a verb to show a completed action in simple beginner sentences.', 'Gunakan 了 setelah kata kerja untuk menunjukkan aksi sudah selesai dalam kalimat pemula.', '[{"simplified":"我吃了。","traditional":"我吃了。","pinyin":"Wǒ chī le.","meaning":"I ate.","meaning_id":"Aku sudah makan."},{"simplified":"你去过吗？","traditional":"你去過嗎？","pinyin":"Nǐ qù guò ma?","meaning":"Have you been there?","meaning_id":"Kamu pernah ke sana?"}]'::jsonb, 1, array['past', 'grammar', 'beginner']::text[], false),
  ('pattern_hui_neng', '会 / 能 + verb', '会 / 能 + kata kerja', 'ability', 'kemampuan', 'Subject + 会/能 + verb', 'Use 会 for learned skills and 能 for ability or possibility.', 'Gunakan 会 untuk kemampuan yang dipelajari dan 能 untuk kemampuan atau kemungkinan.', '[{"simplified":"我会说中文。","traditional":"我會說中文。","pinyin":"Wǒ huì shuō zhōng wén.","meaning":"I can speak Chinese.","meaning_id":"Aku bisa berbicara Mandarin."},{"simplified":"你会写吗？","traditional":"你會寫嗎？","pinyin":"Nǐ huì xiě ma?","meaning":"Can you write it?","meaning_id":"Kamu bisa menulis?"}]'::jsonb, 1, array['ability', 'beginner']::text[], false),
  ('pattern_weather_sentence', 'Weather statement', 'Kalimat cuaca', 'talking about weather', 'bicara tentang cuaca', 'Time + 天气 + adjective', 'Use 天气 to talk about weather conditions.', 'Gunakan 天气 untuk membicarakan kondisi cuaca.', '[{"simplified":"今天天气很好。","traditional":"今天天氣很好。","pinyin":"Jīn tiān tiān qì hěn hǎo.","meaning":"The weather is good today.","meaning_id":"Hari ini cuacanya bagus."},{"simplified":"明天下雨吗？","traditional":"明天下雨嗎？","pinyin":"Míng tiān xià yǔ ma?","meaning":"Will it rain tomorrow?","meaning_id":"Besok hujan?"}]'::jsonb, 1, array['weather', 'beginner']::text[], false),
  ('pattern_wear_clothes', '穿 + clothes', '穿 + pakaian', 'wearing clothes', 'memakai pakaian', 'Subject + 穿 + clothes', 'Use 穿 with clothes and shoes.', 'Gunakan 穿 untuk pakaian dan sepatu.', '[{"simplified":"我穿新衣服。","traditional":"我穿新衣服。","pinyin":"Wǒ chuān xīn yī fu.","meaning":"I wear new clothes.","meaning_id":"Aku pakai baju baru."},{"simplified":"你穿什么颜色？","traditional":"你穿什麼顏色？","pinyin":"Nǐ chuān shén me yán sè?","meaning":"What color are you wearing?","meaning_id":"Kamu pakai warna apa?"}]'::jsonb, 1, array['clothes', 'beginner']::text[], false),
  ('pattern_color_noun', 'Color words', 'Kata warna', 'using colors', 'memakai warna', 'Color + 的 + noun', 'Use colors to describe things directly or with 的.', 'Gunakan warna untuk mendeskripsikan benda langsung atau dengan 的.', '[{"simplified":"我喜欢蓝色。","traditional":"我喜歡藍色。","pinyin":"Wǒ xǐ huān lán sè.","meaning":"I like blue.","meaning_id":"Aku suka biru."},{"simplified":"这个是黑色。","traditional":"這個是黑色。","pinyin":"Zhè ge shì hēi sè.","meaning":"This one is black.","meaning_id":"Yang ini hitam."}]'::jsonb, 1, array['color', 'beginner']::text[], false),
  ('pattern_body_hurts', 'Body part + 疼', 'Bagian tubuh + 疼', 'saying something hurts', 'mengatakan bagian tubuh sakit', 'Body part + 疼', 'Use 疼 after a body part to say it hurts.', 'Gunakan 疼 setelah bagian tubuh untuk mengatakan sakit.', '[{"simplified":"我头疼。","traditional":"我頭疼。","pinyin":"Wǒ tóu téng.","meaning":"My head hurts.","meaning_id":"Kepalaku sakit."},{"simplified":"我手疼。","traditional":"我手疼。","pinyin":"Wǒ shǒu téng.","meaning":"My hand hurts.","meaning_id":"Tanganku sakit."}]'::jsonb, 1, array['health', 'body', 'beginner']::text[], false),
  ('pattern_work_study_actions', 'Work/study actions', 'Aksi kerja/belajar', 'work and study verbs', 'kata kerja kerja/belajar', '上班 / 下班 / 上课', 'Use 上/下 with work and class routines.', 'Gunakan 上/下 untuk rutinitas kerja dan kelas.', '[{"simplified":"我今天上班。","traditional":"我今天上班。","pinyin":"Wǒ jīn tiān shàng bān.","meaning":"I work today.","meaning_id":"Hari ini aku kerja."},{"simplified":"你学习什么？","traditional":"你學習什麼？","pinyin":"Nǐ xué xí shén me?","meaning":"What do you study?","meaning_id":"Kamu belajar apa?"}]'::jsonb, 1, array['work', 'study', 'beginner']::text[], false),
  ('pattern_hobby_like', '喜欢 + hobby', '喜欢 + hobi', 'talking about hobbies', 'bicara tentang hobi', '喜欢 + noun/verb phrase', 'Use 喜欢 to talk about hobbies and activities.', 'Gunakan 喜欢 untuk bicara tentang hobi dan aktivitas.', '[{"simplified":"我喜欢音乐。","traditional":"我喜歡音樂。","pinyin":"Wǒ xǐ huān yīn yuè.","meaning":"I like music.","meaning_id":"Aku suka musik."},{"simplified":"你喜欢看书吗？","traditional":"你喜歡看書嗎？","pinyin":"Nǐ xǐ huān kàn shū ma?","meaning":"Do you like reading?","meaning_id":"Kamu suka membaca?"}]'::jsonb, 1, array['hobby', 'preference', 'beginner']::text[], false),
  ('pattern_feeling_hen', '很 + feeling', '很 + perasaan', 'expressing feelings', 'mengungkapkan perasaan', 'Subject + 很 + feeling adjective', 'Use 很 before many feeling adjectives.', 'Gunakan 很 sebelum banyak kata sifat perasaan.', '[{"simplified":"我很高兴！","traditional":"我很高興！","pinyin":"Wǒ hěn gāo xìng!","meaning":"I am very happy!","meaning_id":"Aku sangat senang!"},{"simplified":"他很累。","traditional":"他很累。","pinyin":"Tā hěn lèi.","meaning":"He is tired.","meaning_id":"Dia lelah."}]'::jsonb, 1, array['feeling', 'beginner']::text[], false),
  ('pattern_place_location', 'Place + 在哪里?', 'Tempat + 在哪里?', 'asking where places are', 'bertanya lokasi tempat', 'Place + 在哪里?', 'Use 在哪里 to ask where a place is.', 'Gunakan 在哪里 untuk bertanya lokasi tempat.', '[{"simplified":"医院在哪里？","traditional":"醫院在哪裡？","pinyin":"Yī yuàn zài nǎ lǐ?","meaning":"Where is the hospital?","meaning_id":"Rumah sakitnya di mana?"},{"simplified":"商店在这里。","traditional":"商店在這裡。","pinyin":"Shāng diàn zài zhè lǐ.","meaning":"The shop is here.","meaning_id":"Tokonya di sini."}]'::jsonb, 1, array['place', 'location', 'beginner']::text[], false),
  ('pattern_restaurant_request', 'Restaurant request', 'Permintaan restoran', 'asking in restaurant', 'meminta di restoran', '我要 / 有...吗?', 'Use 我要 to order and 有...吗 to ask if something is available.', 'Gunakan 我要 untuk pesan dan 有...吗 untuk bertanya apakah sesuatu tersedia.', '[{"simplified":"我要点菜。","traditional":"我要點菜。","pinyin":"Wǒ yào diǎn cài.","meaning":"I want to order food.","meaning_id":"Aku mau pesan makanan."},{"simplified":"有菜单吗？","traditional":"有菜單嗎？","pinyin":"Yǒu cài dān ma?","meaning":"Do you have a menu?","meaning_id":"Ada menu?"}]'::jsonb, 1, array['restaurant', 'ordering', 'beginner']::text[], false),
  ('pattern_shop_questions', 'Shop questions', 'Pertanyaan toko', 'asking price/payment', 'bertanya harga/pembayaran', '价格多少？/ 可以刷卡吗？', 'Use short direct questions for shopping.', 'Gunakan pertanyaan pendek dan langsung untuk belanja.', '[{"simplified":"价格多少？","traditional":"價格多少？","pinyin":"Jià gé duō shao?","meaning":"How much is the price?","meaning_id":"Harganya berapa?"},{"simplified":"可以刷卡吗？","traditional":"可以刷卡嗎？","pinyin":"Kě yǐ shuā kǎ ma?","meaning":"Can I pay by card?","meaning_id":"Bisa bayar pakai kartu?"}]'::jsonb, 1, array['shop', 'payment', 'beginner']::text[], false),
  ('pattern_help_requests', 'Help requests', 'Permintaan bantuan', 'asking for help', 'meminta bantuan', '请 + request', 'Use 请 to make help requests polite.', 'Gunakan 请 agar permintaan bantuan terdengar sopan.', '[{"simplified":"请帮我。","traditional":"請幫我。","pinyin":"Qǐng bāng wǒ.","meaning":"Please help me.","meaning_id":"Tolong bantu aku."},{"simplified":"请再说一次。","traditional":"請再說一次。","pinyin":"Qǐng zài shuō yí cì.","meaning":"Please say it again.","meaning_id":"Tolong ulangi lagi."}]'::jsonb, 1, array['help', 'polite', 'beginner']::text[], false),
  ('pattern_making_plans', 'Time + 一起 + action', 'Waktu + 一起 + aksi', 'making simple plans', 'membuat rencana sederhana', 'Time + 一起 + verb', 'Use 一起 for doing something together.', 'Gunakan 一起 untuk melakukan sesuatu bersama.', '[{"simplified":"明天见面。","traditional":"明天見面。","pinyin":"Míng tiān jiàn miàn.","meaning":"Meet tomorrow.","meaning_id":"Ketemuan besok."},{"simplified":"我们一起去！","traditional":"我們一起去！","pinyin":"Wǒ men yì qǐ qù!","meaning":"Let''s go together!","meaning_id":"Ayo pergi bersama!"}]'::jsonb, 1, array['plans', 'beginner']::text[], false)
insert into public.sentences (external_id, simplified, traditional, meaning_en, meaning_id, literal_meaning_en, literal_meaning_id, pinyin_diacritic, pinyin_numbered, pinyin_syllables, tone_pattern, notes_en, notes_id, audio_url, order_index, tags, is_reviewable) values
  ('sentence_wo_shi_wo', '我是我。', '我是我。', 'I am me.', 'Saya adalah saya.', 'I am I.', 'Aku adalah aku.', 'wǒ shì wǒ', 'wo3 shi4 wo3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '3-4-3', 'A simple identity sentence using 是.', 'Kalimat identitas sederhana menggunakan 是.', null, 1, array['identity', 'beginner']::text[], true),
  ('sentence_wo_you', '我有。', '我有。', 'I have it.', 'Saya punya.', 'I have.', 'Aku punya.', 'wǒ yǒu', 'wo3 you3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"有","text":"yǒu","tone":3}]'::jsonb, '3-3', 'Basic possession sentence. Object often comes after 有.', 'Kalimat kepemilikan dasar. Objek biasanya mengikuti 有.', null, 2, array['possession', 'beginner']::text[], true),
  ('sentence_wo_qu', '我去。', '我去。', 'I’m going.', 'Saya pergi.', 'I go.', 'Aku pergi.', 'wǒ qù', 'wo3 qu4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '3-4', 'Simple subject + verb sentence.', 'Kalimat subjek + kata kerja sederhana.', null, 1, array['action', 'beginner']::text[], true),
  ('sentence_wo_xiang_qu', '我想去。', '我想去。', 'I want to go.', 'Saya ingin pergi.', 'I want go.', 'Aku mau pergi.', 'wǒ xiǎng qù', 'wo3 xiang3 qu4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"想","text":"xiǎng","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '3-3-4', '想 before a verb expresses wanting to do something.', '想 sebelum kata kerja menyatakan keinginan melakukan sesuatu.', null, 2, array['desire', 'beginner']::text[], true),
  ('sentence_ni_qu_ma', '你去吗？', '你去嗎？', 'Are you going?', 'Kamu pergi?', 'You go?', 'Kamu pergi?', 'nǐ qù ma', 'ni3 qu4 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"去","text":"qù","tone":4},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-4-0', '吗 turns any statement into a yes/no question.', '吗 mengubah pernyataan apapun menjadi pertanyaan ya/tidak.', null, 1, array['question', 'beginner']::text[], true),
  ('sentence_ni_shi_shei', '你是谁？', '你是誰？', 'Who are you?', 'Kamu siapa?', 'You are who?', 'Kamu adalah siapa?', 'nǐ shì shéi', 'ni3 shi4 shei2', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"谁","text":"shéi","tone":2}]'::jsonb, '3-4-2', 'In Mandarin, question words stay in position — no inversion needed.', 'Dalam Mandarin, kata tanya tetap di posisinya — tidak perlu dibalik.', null, 2, array['question', 'beginner']::text[], true),
  ('sentence_jintian_wo_qu', '今天我去。', '今天我去。', 'Today I’m going.', 'Hari ini saya pergi.', 'Today I go.', 'Hari ini aku pergi.', 'jīn tiān wǒ qù', 'jin1 tian1 wo3 qu4', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '1-1-3-4', 'Time word comes first in Mandarin sentences.', 'Kata waktu selalu di awal kalimat Mandarin.', null, 1, array['time', 'beginner']::text[], true),
  ('sentence_xianzai_wo_kan', '现在我看。', '現在我看。', 'Now I watch.', 'Sekarang saya lihat.', 'Now I watch.', 'Sekarang aku lihat.', 'xiàn zài wǒ kàn', 'xian4 zai4 wo3 kan4', '[{"hanzi":"现","text":"xiàn","tone":4},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"看","text":"kàn","tone":4}]'::jsonb, '4-4-3-4', '现在 as a time word comes before the subject.', '现在 sebagai kata waktu muncul sebelum subjek.', null, 2, array['time', 'beginner']::text[], true),
  ('sentence_wo_zai_jia', '我在家。', '我在家。', 'I’m at home.', 'Saya di rumah.', 'I at home.', 'Aku di rumah.', 'wǒ zài jiā', 'wo3 zai4 jia1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"家","text":"jiā","tone":1}]'::jsonb, '3-4-1', '在 marks location — subject + 在 + place.', '在 menandai lokasi — subjek + 在 + tempat.', null, 1, array['location', 'beginner']::text[], true),
  ('sentence_wo_qu_xuexiao', '我去学校。', '我去學校。', 'I go to school.', 'Saya pergi ke sekolah.', 'I go school.', 'Aku pergi sekolah.', 'wǒ qù xué xiào', 'wo3 qu4 xue2 xiao4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4},{"hanzi":"学","text":"xué","tone":2},{"hanzi":"校","text":"xiào","tone":4}]'::jsonb, '3-4-2-4', 'No preposition needed before the destination.', 'Tidak perlu preposisi sebelum tujuan.', null, 2, array['movement', 'beginner']::text[], true),
  ('sentence_wo_yao_shui', '我要水。', '我要水。', 'I want water.', 'Saya mau air.', 'I want water.', 'Aku mau air.', 'wǒ yào shuǐ', 'wo3 yao4 shui3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '3-4-3', '要 means "want" — you will learn this fully in a later pack.', '要 berarti "mau" — kamu akan belajar ini lebih lengkap di pack berikutnya.', null, 1, array['food', 'shopping', 'beginner']::text[], true),
  ('sentence_duoshaoqian', '多少钱？', '多少錢？', 'How much is it?', 'Berapa harganya?', 'How much money?', 'Berapa uang?', 'duō shǎo qián', 'duo1 shao3 qian2', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '1-3-2', 'The most useful shopping phrase. No subject needed.', 'Frasa belanja paling berguna. Tidak perlu subjek.', null, 2, array['shopping', 'beginner']::text[], true),
  ('sentence_ta_shi_pengyou', '他是朋友。', '他是朋友。', 'He is a friend.', 'Dia teman.', 'He is friend.', 'Dia adalah teman.', 'tā shì péng yǒu', 'ta1 shi4 peng2 you3', '[{"hanzi":"他","text":"tā","tone":1},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"朋","text":"péng","tone":2},{"hanzi":"友","text":"yǒu","tone":3}]'::jsonb, '1-4-2-3', 'No article needed — just subject + 是 + noun.', 'Tidak perlu artikel — cukup subjek + 是 + kata benda.', null, 1, array['identity', 'people', 'beginner']::text[], true),
  ('sentence_women_shi_jiaren', '我们是家人。', '我們是家人。', 'We are family.', 'Kami/kita keluarga.', 'We are family.', 'Kami adalah keluarga.', 'wǒ men shì jiā rén', 'wo3 men0 shi4 jia1 ren2', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"们","text":"men","tone":0},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"家","text":"jiā","tone":1},{"hanzi":"人","text":"rén","tone":2}]'::jsonb, '3-0-4-1-2', '家人 means family members — 家 home + 人 person.', '家人 berarti anggota keluarga — 家 rumah + 人 orang.', null, 2, array['family', 'beginner']::text[], true),
  ('sentence_hen_da', '很大。', '很大。', 'Very big / quite big.', 'Besar.', 'Very big.', 'Sangat besar.', 'hěn dà', 'hen3 da4', '[{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"大","text":"dà","tone":4}]'::jsonb, '3-4', '很 before adjective is the standard Mandarin descriptor pattern.', '很 sebelum kata sifat adalah pola deskriptor standar Mandarin.', null, 1, array['description', 'beginner']::text[], true),
  ('sentence_zhe_hen_gui', '这很贵。', '這很貴。', 'This is expensive.', 'Ini mahal.', 'This very expensive.', 'Ini sangat mahal.', 'zhè hěn guì', 'zhe4 hen3 gui4', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"贵","text":"guì","tone":4}]'::jsonb, '4-3-4', 'No verb needed — subject + 很 + adjective is a complete sentence.', 'Tidak perlu kata kerja — subjek + 很 + kata sifat sudah jadi kalimat lengkap.', null, 2, array['description', 'shopping', 'beginner']::text[], true),
  ('sentence_wo_xihuan_shui', '我喜欢水。', '我喜歡水。', 'I like water.', 'Saya suka air.', 'I like water.', 'Aku suka air.', 'wǒ xǐ huān shuǐ', 'wo3 xi3 huan1 shui3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1},{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '3-3-1-3', '喜欢 + object is the standard "like" pattern.', '喜欢 + objek adalah pola standar untuk "suka".', null, 1, array['opinion', 'beginner']::text[], true),
  ('sentence_wo_juede_keyi', '我觉得可以。', '我覺得可以。', 'I think it’s okay.', 'Menurut saya boleh/oke.', 'I feel can.', 'Aku rasa boleh.', 'wǒ jué de kě yǐ', 'wo3 jue2 de0 ke3 yi3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"觉","text":"jué","tone":2},{"hanzi":"得","text":"de","tone":0},{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3}]'::jsonb, '3-2-0-3-3', '觉得 expresses personal opinion — "I think/feel that".', '觉得 menyatakan pendapat pribadi — "aku rasa/pikir".', null, 2, array['opinion', 'beginner']::text[], true),
  ('sentence_yi_ge', '一个。', '一個。', 'One item/person.', 'Satu buah/orang.', 'One [item].', 'Satu [benda].', 'yí ge', 'yi2 ge0', '[{"hanzi":"一","text":"yí","tone":2},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '2-0', '个 is the general measure word. Numbers always come before the measure word.', '个 adalah kata bantu bilangan umum. Angka selalu muncul sebelum kata bantu bilangan.', null, 1, array['number', 'measure_word', 'beginner']::text[], true),
  ('sentence_san_ge', '三个。', '三個。', 'Three items/people.', 'Tiga buah/orang.', 'Three [items].', 'Tiga [benda].', 'sān ge', 'san1 ge0', '[{"hanzi":"三","text":"sān","tone":1},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '1-0', 'Same pattern as 一个 — number + 个.', 'Pola yang sama dengan 一个 — angka + 个.', null, 2, array['number', 'measure_word', 'beginner']::text[], true),
  ('sentence_shiyi_ge', '十一个。', '十一個。', 'Eleven items/people.', 'Sebelas buah/orang.', 'Eleven [items].', 'Sebelas [benda].', 'shí yī ge', 'shi2 yi1 ge0', '[{"hanzi":"十","text":"shí","tone":2},{"hanzi":"一","text":"yī","tone":1},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '2-1-0', 'Same number + 个 pattern, just with bigger numbers.', 'Pola angka + 个 yang sama, hanya angkanya lebih besar.', null, 1, array['number', 'measure_word', 'beginner']::text[], true),
  ('sentence_ershi_kuai', '二十块。', '二十塊。', 'Twenty yuan/dollars.', 'Dua puluh yuan/dolar.', 'Twenty yuan.', 'Dua puluh yuan.', 'èr shí kuài', 'er4 shi2 kuai4', '[{"hanzi":"二","text":"èr","tone":4},{"hanzi":"十","text":"shí","tone":2},{"hanzi":"块","text":"kuài","tone":4}]'::jsonb, '4-2-4', '块 is the spoken word for Chinese yuan — you will see it often in prices.', '块 adalah kata lisan untuk yuan China — sering muncul saat bicara harga.', null, 2, array['number', 'money', 'beginner']::text[], true),
  ('sentence_zuotian_wo_qu', '昨天我去。', '昨天我去。', 'Yesterday I went.', 'Kemarin saya pergi.', 'Yesterday I go.', 'Kemarin aku pergi.', 'zuó tiān wǒ qù', 'zuo2 tian1 wo3 qu4', '[{"hanzi":"昨","text":"zuó","tone":2},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '2-1-3-4', 'Time word first — 昨天 before subject. Mandarin doesn''t change verb tense, context tells the time.', 'Kata waktu di depan — 昨天 sebelum subjek. Mandarin tidak mengubah kata kerja, konteks yang menunjukkan waktu.', null, 1, array['time', 'past', 'beginner']::text[], true),
  ('sentence_xingqiyi_ni_lai_ma', '星期一你来吗？', '星期一你來嗎？', 'Are you coming on Monday?', 'Hari Senin kamu datang?', 'Monday you come?', 'Senin kamu datang?', 'xīng qī yī nǐ lái ma', 'xing1 qi1 yi1 ni3 lai2 ma0', '[{"hanzi":"星","text":"xīng","tone":1},{"hanzi":"期","text":"qī","tone":1},{"hanzi":"一","text":"yī","tone":1},{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"来","text":"lái","tone":2},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '1-1-1-3-2-0', 'Day of week comes first, then subject and verb.', 'Hari dalam seminggu di depan, baru subjek dan kata kerja.', null, 2, array['time', 'question', 'beginner']::text[], true),
  ('sentence_yi_ge_ren', '一个人。', '一個人。', 'One person.', 'Satu orang.', 'One person.', 'Satu orang.', 'yí ge rén', 'yi2 ge0 ren2', '[{"hanzi":"一","text":"yí","tone":2},{"hanzi":"个","text":"ge","tone":0},{"hanzi":"人","text":"rén","tone":2}]'::jsonb, '2-0-2', 'Number + measure word + noun — the standard counting pattern.', 'Angka + kata bantu bilangan + kata benda — pola hitungan standar.', null, 1, array['measure_word', 'beginner']::text[], true),
  ('sentence_yi_bei_shui', '一杯水。', '一杯水。', 'One cup of water.', 'Satu gelas air.', 'One cup water.', 'Satu cangkir air.', 'yì bēi shuǐ', 'yi4 bei1 shui3', '[{"hanzi":"一","text":"yì","tone":4},{"hanzi":"杯","text":"bēi","tone":1},{"hanzi":"水","text":"shuǐ","tone":3}]'::jsonb, '4-1-3', '杯 is the measure word for drinks in cups or glasses.', '杯 adalah kata bantu bilangan untuk minuman dalam cangkir atau gelas.', null, 2, array['measure_word', 'food', 'beginner']::text[], true),
  ('sentence_zhege_duoshaoqian', '这个多少钱？', '這個多少錢？', 'How much is this one?', 'Yang ini berapa harganya?', 'This one how much money?', 'Yang ini berapa uang?', 'zhè ge duō shǎo qián', 'zhe4 ge0 duo1 shao3 qian2', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"个","text":"ge","tone":0},{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '4-0-1-3-2', '这个 + 多少钱 — the most useful shopping sentence.', '这个 + 多少钱 — kalimat belanja paling berguna.', null, 1, array['shopping', 'demonstrative', 'beginner']::text[], true),
  ('sentence_ni_yao_nage', '你要哪个？', '你要哪個？', 'Which one do you want?', 'Kamu mau yang mana?', 'You want which one?', 'Kamu mau yang mana?', 'nǐ yào nǎ ge', 'ni3 yao4 na3 ge0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"哪","text":"nǎ","tone":3},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '3-4-3-0', '哪个 replaces the noun when asking which one to choose.', '哪个 menggantikan kata benda saat menanya pilihan.', null, 2, array['question', 'demonstrative', 'beginner']::text[], true),
  ('sentence_mifan_haochi', '米饭很好吃。', '米飯很好吃。', 'Rice is tasty.', 'Nasinya enak.', 'Cooked rice very tasty.', 'Nasi sangat enak.', 'mǐ fàn hěn hǎo chī', 'mi3 fan4 hen3 hao3 chi1', '[{"hanzi":"米","text":"mǐ","tone":3},{"hanzi":"饭","text":"fàn","tone":4},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"好","text":"hǎo","tone":3},{"hanzi":"吃","text":"chī","tone":1}]'::jsonb, '3-4-3-3-1', 'Subject + 很 + 好吃 — the standard pattern for saying food is tasty.', 'Subjek + 很 + 好吃 — pola standar untuk bilang makanan enak.', null, 1, array['food', 'description', 'beginner']::text[], true),
  ('sentence_wo_yao_miantiao', '我要面条。', '我要麵條。', 'I want noodles.', 'Saya mau mi.', 'I want noodles.', 'Aku mau mie.', 'wǒ yào miàn tiáo', 'wo3 yao4 mian4 tiao2', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"面","text":"miàn","tone":4},{"hanzi":"条","text":"tiáo","tone":2}]'::jsonb, '3-4-4-2', '要 means "want" here — a very useful ordering phrase.', '要 berarti "mau" di sini — frasa memesan yang sangat berguna.', null, 2, array['food', 'ordering', 'beginner']::text[], true),
  ('sentence_qing_yibei_cha', '请一杯茶。', '請一杯茶。', 'A cup of tea, please.', 'Tolong segelas teh.', 'Please one cup tea.', 'Tolong satu cangkir teh.', 'qǐng yì bēi chá', 'qing3 yi4 bei1 cha2', '[{"hanzi":"请","text":"qǐng","tone":3},{"hanzi":"一","text":"yì","tone":4},{"hanzi":"杯","text":"bēi","tone":1},{"hanzi":"茶","text":"chá","tone":2}]'::jsonb, '3-4-1-2', '请 + order — the polite way to order anything.', '请 + pesanan — cara sopan untuk memesan apapun.', null, 1, array['ordering', 'drink', 'beginner']::text[], true),
  ('sentence_wo_yao_kafei', '我要咖啡。', '我要咖啡。', 'I want coffee.', 'Saya mau kopi.', 'I want coffee.', 'Aku mau kopi.', 'wǒ yào kā fēi', 'wo3 yao4 ka1 fei1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"咖","text":"kā","tone":1},{"hanzi":"啡","text":"fēi","tone":1}]'::jsonb, '3-4-1-1', '我要 + drink — direct ordering phrase used everywhere.', '我要 + minuman — frasa memesan langsung yang dipakai di mana-mana.', null, 2, array['ordering', 'drink', 'beginner']::text[], true),
  ('sentence_wo_zuo_gongjiaoche', '我坐公交车。', '我坐公交車。', 'I take the bus.', 'Saya naik bus.', 'I sit bus.', 'Aku duduk bus.', 'wǒ zuò gōng jiāo chē', 'wo3 zuo4 gong1 jiao1 che1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"坐","text":"zuò","tone":4},{"hanzi":"公","text":"gōng","tone":1},{"hanzi":"交","text":"jiāo","tone":1},{"hanzi":"车","text":"chē","tone":1}]'::jsonb, '3-4-1-1-1', '坐 means "sit" but is used for taking vehicles — 坐车 means "take a vehicle".', '坐 berarti "duduk" tapi dipakai untuk naik kendaraan — 坐车 berarti "naik kendaraan".', null, 1, array['transport', 'beginner']::text[], true),
  ('sentence_ni_zuo_ditie_ma', '你坐地铁吗？', '你坐地鐵嗎？', 'Do you take the subway?', 'Kamu naik metro?', 'You sit subway?', 'Kamu duduk subway?', 'nǐ zuò dì tiě ma', 'ni3 zuo4 di4 tie3 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"坐","text":"zuò","tone":4},{"hanzi":"地","text":"dì","tone":4},{"hanzi":"铁","text":"tiě","tone":3},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-4-4-3-0', 'Same 坐 pattern — 坐 + any vehicle means "take" that vehicle.', 'Pola 坐 yang sama — 坐 + kendaraan apapun berarti "naik" kendaraan itu.', null, 2, array['transport', 'question', 'beginner']::text[], true),
  ('sentence_yizhi_zou', '一直走。', '一直走。', 'Go straight.', 'Jalan terus.', 'Straight walk.', 'Lurus jalan.', 'yì zhí zǒu', 'yi4 zhi2 zou3', '[{"hanzi":"一","text":"yì","tone":4},{"hanzi":"直","text":"zhí","tone":2},{"hanzi":"走","text":"zǒu","tone":3}]'::jsonb, '4-2-3', '一直 + verb = keep doing something straight/continuously. Used for giving directions.', '一直 + kata kerja = terus melakukan sesuatu lurus/terus-menerus. Dipakai untuk memberi petunjuk arah.', null, 1, array['direction', 'beginner']::text[], true),
  ('sentence_zuobian_zhuan', '左边转。', '左邊轉。', 'Turn left.', 'Belok kiri.', 'Left side turn.', 'Sisi kiri belok.', 'zuǒ biān zhuǎn', 'zuo3 bian1 zhuan3', '[{"hanzi":"左","text":"zuǒ","tone":3},{"hanzi":"边","text":"biān","tone":1},{"hanzi":"转","text":"zhuǎn","tone":3}]'::jsonb, '3-1-3', 'Direction + 转 — the standard way to say "turn [direction]".', 'Arah + 转 — cara standar bilang "belok [arah]".', null, 2, array['direction', 'beginner']::text[], true),
  ('sentence_wo_chi_le', '我吃了。', '我吃了。', 'I ate / I have eaten.', 'Saya sudah makan.', 'I eat [completed].', 'Aku makan [selesai].', 'wǒ chī le', 'wo3 chi1 le0', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"吃","text":"chī","tone":1},{"hanzi":"了","text":"le","tone":0}]'::jsonb, '3-1-0', 'Verb + 了 marks the action as done. Mandarin doesn''t conjugate verbs — 了 does the work.', 'Kata kerja + 了 menandai aksi sudah selesai. Mandarin tidak mengkonjugasikan kata kerja — 了 yang bekerja.', null, 1, array['past', 'grammar', 'beginner']::text[], true),
  ('sentence_ni_kan_guo_ma', '你看过吗？', '你看過嗎？', 'Have you seen it before?', 'Kamu pernah lihat?', 'You watch [experienced]?', 'Kamu lihat [pernah]?', 'nǐ kàn guò ma', 'ni3 kan4 guo4 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"看","text":"kàn","tone":4},{"hanzi":"过","text":"guò","tone":4},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-4-4-0', '过 asks about life experience — have you ever done this? Different from 了 which is about recent events.', '过 menanyakan pengalaman hidup — pernahkah kamu melakukan ini? Beda dari 了 yang soal kejadian baru-baru ini.', null, 2, array['past', 'question', 'grammar', 'beginner']::text[], true),
  ('sentence_wo_hui_shuo_zhongwen', '我会说中文。', '我會說中文。', 'I can speak Chinese.', 'Saya bisa bicara Mandarin.', 'I know-how speak Chinese.', 'Aku bisa berbicara bahasa Mandarin.', 'wǒ huì shuō zhōng wén', 'wo3 hui4 shuo1 zhong1 wen2', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"会","text":"huì","tone":4},{"hanzi":"说","text":"shuō","tone":1},{"hanzi":"中","text":"zhōng","tone":1},{"hanzi":"文","text":"wén","tone":2}]'::jsonb, '3-4-1-1-2', '会 + verb = know how to do something. The most useful sentence for a learner to say.', '会 + kata kerja = bisa melakukan sesuatu karena belajar. Kalimat paling berguna untuk pelajar.', null, 1, array['ability', 'language', 'beginner']::text[], true),
  ('sentence_wo_hui_yidian', '我会一点。', '我會一點。', 'I know a little.', 'Saya bisa sedikit.', 'I know-how a little.', 'Aku bisa sedikit.', 'wǒ huì yì diǎn', 'wo3 hui4 yi4 dian3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"会","text":"huì","tone":4},{"hanzi":"一","text":"yì","tone":4},{"hanzi":"点","text":"diǎn","tone":3}]'::jsonb, '3-4-4-3', 'A humble way to say you have basic ability — perfect for early learners.', 'Cara rendah hati untuk bilang kamu punya kemampuan dasar — pas banget untuk pemula.', null, 2, array['ability', 'beginner']::text[], true),
  ('sentence_jintian_tianqi_hen_hao', '今天天气很好。', '今天天氣很好。', 'The weather is good today.', 'Cuaca hari ini bagus.', 'Today weather very good.', 'Hari ini cuaca sangat bagus.', 'jīn tiān tiān qì hěn hǎo', 'jin1 tian1 tian1 qi4 hen3 hao3', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"气","text":"qì","tone":4},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"好","text":"hǎo","tone":3}]'::jsonb, '1-1-1-4-3-3', 'Time word first, then subject 天气, then 很 + adjective.', 'Kata waktu di depan, lalu subjek 天气, lalu 很 + kata sifat.', null, 1, array['weather', 'beginner']::text[], true),
  ('sentence_mingtian_xiayu_ma', '明天下雨吗？', '明天下雨嗎？', 'Will it rain tomorrow?', 'Besok hujan?', 'Tomorrow fall-rain?', 'Besok hujan?', 'míng tiān xià yǔ ma', 'ming2 tian1 xia4 yu3 ma0', '[{"hanzi":"明","text":"míng","tone":2},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"下","text":"xià","tone":4},{"hanzi":"雨","text":"yǔ","tone":3},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '2-1-4-3-0', '下雨 is a verb phrase — no subject needed for weather expressions.', '下雨 adalah frasa kata kerja — tidak perlu subjek untuk ekspresi cuaca.', null, 2, array['weather', 'question', 'beginner']::text[], true),
  ('sentence_wo_chuan_xin_yifu', '我穿新衣服。', '我穿新衣服。', 'I wear new clothes.', 'Saya memakai pakaian baru.', 'I wear new clothes.', 'Aku memakai baju baru.', 'wǒ chuān xīn yī fu', 'wo3 chuan1 xin1 yi1 fu0', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"穿","text":"chuān","tone":1},{"hanzi":"新","text":"xīn","tone":1},{"hanzi":"衣","text":"yī","tone":1},{"hanzi":"服","text":"fu","tone":0}]'::jsonb, '3-1-1-1-0', '穿 + clothing — the standard pattern for wearing clothes.', '穿 + pakaian — pola standar untuk memakai pakaian.', null, 1, array['clothes', 'beginner']::text[], true),
  ('sentence_zhe_shuang_xie_hen_gui', '这双鞋很贵。', '這雙鞋很貴。', 'These shoes are expensive.', 'Sepatu ini mahal.', 'This pair shoes very expensive.', 'Sepasang sepatu ini sangat mahal.', 'zhè shuāng xié hěn guì', 'zhe4 shuang1 xie2 hen3 gui4', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"双","text":"shuāng","tone":1},{"hanzi":"鞋","text":"xié","tone":2},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"贵","text":"guì","tone":4}]'::jsonb, '4-1-2-3-4', '双 is the measure word for pairs (shoes, socks, hands). Subject + 很 + adjective.', '双 adalah kata bantu bilangan untuk pasangan (sepatu, kaus kaki, tangan). Subjek + 很 + kata sifat.', null, 2, array['clothes', 'shopping', 'beginner']::text[], true),
  ('sentence_wo_xihuan_lanse', '我喜欢蓝色。', '我喜歡藍色。', 'I like blue.', 'Saya suka warna biru.', 'I like blue color.', 'Aku suka warna biru.', 'wǒ xǐ huān lán sè', 'wo3 xi3 huan1 lan2 se4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1},{"hanzi":"蓝","text":"lán","tone":2},{"hanzi":"色","text":"sè","tone":4}]'::jsonb, '3-3-1-2-4', '喜欢 + color — expressing color preference.', '喜欢 + warna — mengungkapkan preferensi warna.', null, 1, array['color', 'preference', 'beginner']::text[], true),
  ('sentence_zhege_shi_heise', '这个是黑色。', '這個是黑色。', 'This one is black.', 'Yang ini hitam.', 'This one is black color.', 'Yang ini berwarna hitam.', 'zhè ge shì hēi sè', 'zhe4 ge0 shi4 hei1 se4', '[{"hanzi":"这","text":"zhè","tone":4},{"hanzi":"个","text":"ge","tone":0},{"hanzi":"是","text":"shì","tone":4},{"hanzi":"黑","text":"hēi","tone":1},{"hanzi":"色","text":"sè","tone":4}]'::jsonb, '4-0-4-1-4', '这个 + 是 + color — identifying the color of something.', '这个 + 是 + warna — mengidentifikasi warna sesuatu.', null, 2, array['color', 'description', 'beginner']::text[], true),
  ('sentence_wo_tou_teng', '我头疼。', '我頭疼。', 'My head hurts.', 'Kepala saya sakit.', 'My head hurts.', 'Kepalaku sakit.', 'wǒ tóu téng', 'wo3 tou2 teng2', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"头","text":"tóu","tone":2},{"hanzi":"疼","text":"téng","tone":2}]'::jsonb, '3-2-2', 'Body part + 疼 — the pattern for saying something hurts. No verb needed.', 'Bagian tubuh + 疼 — pola untuk bilang sesuatu sakit. Tidak perlu kata kerja.', null, 1, array['health', 'body', 'beginner']::text[], true),
  ('sentence_wo_shengbing_le', '我生病了。', '我生病了。', 'I got sick.', 'Saya sakit.', 'I got sick [completed].', 'Aku jatuh sakit.', 'wǒ shēng bìng le', 'wo3 sheng1 bing4 le0', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"生","text":"shēng","tone":1},{"hanzi":"病","text":"bìng","tone":4},{"hanzi":"了","text":"le","tone":0}]'::jsonb, '3-1-4-0', '生病了 — 了 marks that the sickness has happened. A common way to say you''re sick.', '生病了 — 了 menandai bahwa sakitnya sudah terjadi. Cara umum bilang kamu sakit.', null, 2, array['health', 'beginner']::text[], true),
  ('sentence_wo_jintian_shangban', '我今天上班。', '我今天上班。', 'I work today.', 'Saya masuk kerja hari ini.', 'I today go-to-work.', 'Aku hari ini kerja.', 'wǒ jīn tiān shàng bān', 'wo3 jin1 tian1 shang4 ban1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"上","text":"shàng","tone":4},{"hanzi":"班","text":"bān","tone":1}]'::jsonb, '3-1-1-4-1', 'Time word 今天 before subject — standard word order.', 'Kata waktu 今天 sebelum subjek — urutan kata standar.', null, 1, array['work', 'beginner']::text[], true),
  ('sentence_ni_mang_ma', '你忙吗？', '你忙嗎？', 'Are you busy?', 'Kamu sibuk?', 'You busy?', 'Kamu sibuk?', 'nǐ máng ma', 'ni3 mang2 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"忙","text":"máng","tone":2},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-2-0', 'A common opener in Chinese conversation — checking in on someone.', 'Pembuka yang umum dalam percakapan Mandarin — mengecek kondisi seseorang.', null, 2, array['work', 'question', 'beginner']::text[], true),
  ('sentence_wo_xihuan_yinyue', '我喜欢音乐。', '我喜歡音樂。', 'I like music.', 'Saya suka musik.', 'I like music.', 'Aku suka musik.', 'wǒ xǐ huān yīn yuè', 'wo3 xi3 huan1 yin1 yue4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1},{"hanzi":"音","text":"yīn","tone":1},{"hanzi":"乐","text":"yuè","tone":4}]'::jsonb, '3-3-1-1-4', '喜欢 + hobby — the standard way to express what you enjoy.', '喜欢 + hobi — cara standar mengungkapkan apa yang kamu sukai.', null, 1, array['hobby', 'preference', 'beginner']::text[], true),
  ('sentence_ni_xihuan_wan_youxi_ma', '你喜欢玩游戏吗？', '你喜歡玩遊戲嗎？', 'Do you like playing games?', 'Kamu suka main game?', 'You like play games?', 'Kamu suka main game?', 'nǐ xǐ huān wán yóu xì ma', 'ni3 xi3 huan1 wan2 you2 xi4 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1},{"hanzi":"玩","text":"wán","tone":2},{"hanzi":"游","text":"yóu","tone":2},{"hanzi":"戏","text":"xì","tone":4},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-3-1-2-2-4-0', '喜欢 + verb phrase — you can follow 喜欢 with a verb directly.', '喜欢 + frasa kata kerja — kamu bisa langsung ikuti 喜欢 dengan kata kerja.', null, 2, array['hobby', 'question', 'beginner']::text[], true),
  ('sentence_wo_hen_lei', '我很累。', '我很累。', 'I’m tired.', 'Saya lelah.', 'I very tired.', 'Aku sangat lelah.', 'wǒ hěn lèi', 'wo3 hen3 lei4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"很","text":"hěn","tone":3},{"hanzi":"累","text":"lèi","tone":4}]'::jsonb, '3-3-4', 'Subject + 很 + feeling adjective — the standard pattern for expressing feelings.', 'Subjek + 很 + kata sifat perasaan — pola standar untuk mengungkapkan perasaan.', null, 1, array['feeling', 'beginner']::text[], true),
  ('sentence_ni_meishi_ma', '你没事吗？', '你沒事嗎？', 'Are you okay?', 'Kamu tidak apa-apa?', 'You no-matter?', 'Kamu tidak apa-apa?', 'nǐ méi shì ma', 'ni3 mei2 shi4 ma0', '[{"hanzi":"你","text":"nǐ","tone":3},{"hanzi":"没","text":"méi","tone":2},{"hanzi":"事","text":"shì","tone":4},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-2-4-0', 'A caring way to check in — "are you okay?" Used when someone seems upset.', 'Cara peduli untuk mengecek keadaan seseorang — "kamu baik-baik saja?" Dipakai saat seseorang terlihat tidak baik.', null, 2, array['feeling', 'question', 'beginner']::text[], true),
  ('sentence_wo_zai_canting', '我在餐厅。', '我在餐廳。', 'I’m at the restaurant.', 'Saya di restoran.', 'I at restaurant.', 'Aku di restoran.', 'wǒ zài cān tīng', 'wo3 zai4 can1 ting1', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"餐","text":"cān","tone":1},{"hanzi":"厅","text":"tīng","tone":1}]'::jsonb, '3-4-1-1', '在 + place — saying where you are right now.', '在 + tempat — bilang di mana kamu berada sekarang.', null, 1, array['place', 'location', 'beginner']::text[], true),
  ('sentence_yiyuan_zai_nali', '医院在哪里？', '醫院在哪裡？', 'Where is the hospital?', 'Rumah sakit di mana?', 'Hospital at where?', 'Rumah sakit ada di mana?', 'yī yuàn zài nǎ lǐ', 'yi1 yuan4 zai4 na3 li3', '[{"hanzi":"医","text":"yī","tone":1},{"hanzi":"院","text":"yuàn","tone":4},{"hanzi":"在","text":"zài","tone":4},{"hanzi":"哪","text":"nǎ","tone":3},{"hanzi":"里","text":"lǐ","tone":3}]'::jsonb, '1-4-4-3-3', 'Place + 在 + 哪里 — asking where something is located.', 'Tempat + 在 + 哪里 — menanyakan di mana sesuatu berada.', null, 2, array['place', 'question', 'beginner']::text[], true),
  ('sentence_wo_yao_diancai', '我要点菜。', '我要點菜。', 'I want to order food.', 'Saya mau pesan makanan.', 'I want order dish.', 'Aku mau pesan makanan.', 'wǒ yào diǎn cài', 'wo3 yao4 dian3 cai4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"要","text":"yào","tone":4},{"hanzi":"点","text":"diǎn","tone":3},{"hanzi":"菜","text":"cài","tone":4}]'::jsonb, '3-4-3-4', '我要 + verb — "I want to do something". Very useful for restaurants.', '我要 + kata kerja — "aku mau melakukan sesuatu". Sangat berguna di restoran.', null, 1, array['restaurant', 'ordering', 'beginner']::text[], true),
  ('sentence_you_caidan_ma', '有菜单吗？', '有菜單嗎？', 'Do you have a menu?', 'Ada menu?', 'Have menu?', 'Ada menu?', 'yǒu cài dān ma', 'you3 cai4 dan1 ma0', '[{"hanzi":"有","text":"yǒu","tone":3},{"hanzi":"菜","text":"cài","tone":4},{"hanzi":"单","text":"dān","tone":1},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-4-1-0', '有 + thing + 吗 — asking if something exists or is available.', '有 + benda + 吗 — menanyakan apakah sesuatu ada atau tersedia.', null, 2, array['restaurant', 'question', 'beginner']::text[], true),
  ('sentence_jiage_duoshao', '价格多少？', '價格多少？', 'How much is the price?', 'Harganya berapa?', 'Price how much?', 'Harganya berapa?', 'jià gé duō shǎo', 'jia4 ge2 duo1 shao3', '[{"hanzi":"价","text":"jià","tone":4},{"hanzi":"格","text":"gé","tone":2},{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, '4-2-1-3', 'Same as 多少钱 but more formal — used when asking about listed prices.', 'Sama seperti 多少钱 tapi lebih formal — dipakai saat menanyakan harga yang tertera.', null, 1, array['shop', 'question', 'beginner']::text[], true),
  ('sentence_keyi_shuaka_ma', '可以刷卡吗？', '可以刷卡嗎？', 'Can I pay by card?', 'Bisa bayar pakai kartu?', 'Can swipe card?', 'Bisa gesek kartu?', 'kě yǐ shuā kǎ ma', 'ke3 yi3 shua1 ka3 ma0', '[{"hanzi":"可","text":"kě","tone":3},{"hanzi":"以","text":"yǐ","tone":3},{"hanzi":"刷","text":"shuā","tone":1},{"hanzi":"卡","text":"kǎ","tone":3},{"hanzi":"吗","text":"ma","tone":0}]'::jsonb, '3-3-1-3-0', '可以 + action + 吗 — asking permission. One of the most useful travel phrases.', '可以 + aksi + 吗 — meminta izin. Salah satu frasa perjalanan paling berguna.', null, 2, array['shop', 'payment', 'beginner']::text[], true),
  ('sentence_qing_bang_wo', '请帮我。', '請幫我。', 'Please help me.', 'Tolong bantu saya.', 'Please help me.', 'Tolong bantu aku.', 'qǐng bāng wǒ', 'qing3 bang1 wo3', '[{"hanzi":"请","text":"qǐng","tone":3},{"hanzi":"帮","text":"bāng","tone":1},{"hanzi":"我","text":"wǒ","tone":3}]'::jsonb, '3-1-3', '请 + verb = polite request. The most essential help phrase.', '请 + kata kerja = permintaan sopan. Frasa minta tolong yang paling penting.', null, 1, array['help', 'polite', 'beginner']::text[], true),
  ('sentence_wo_budong', '我不懂。', '我不懂。', 'I don''t understand.', 'Saya tidak mengerti.', 'I not understand.', 'Aku tidak mengerti.', 'wǒ bù dǒng', 'wo3 bu4 dong3', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"不","text":"bù","tone":4},{"hanzi":"懂","text":"dǒng","tone":3}]'::jsonb, '3-4-3', 'A key survival phrase — admit you don''t understand and ask for help.', 'Frasa bertahan hidup yang penting — akui kamu tidak mengerti dan minta bantuan.', null, 2, array['help', 'communication', 'beginner']::text[], true),
  ('sentence_mingtian_jianmian', '明天见面。', '明天見面。', 'Meet tomorrow.', 'Bertemu besok.', 'Tomorrow meet.', 'Besok bertemu.', 'míng tiān jiàn miàn', 'ming2 tian1 jian4 mian4', '[{"hanzi":"明","text":"míng","tone":2},{"hanzi":"天","text":"tiān","tone":1},{"hanzi":"见","text":"jiàn","tone":4},{"hanzi":"面","text":"miàn","tone":4}]'::jsonb, '2-1-4-4', 'Time word + 见面 — setting up a meeting simply and directly.', 'Kata waktu + 见面 — mengatur pertemuan dengan sederhana dan langsung.', null, 1, array['plans', 'time', 'beginner']::text[], true),
  ('sentence_women_yiqi_qu', '我们一起去。', '我們一起去。', 'Let''s go together.', 'Kita pergi bersama.', 'We together go.', 'Kita pergi bersama.', 'wǒ men yì qǐ qù', 'wo3 men0 yi4 qi3 qu4', '[{"hanzi":"我","text":"wǒ","tone":3},{"hanzi":"们","text":"men","tone":0},{"hanzi":"一","text":"yì","tone":4},{"hanzi":"起","text":"qǐ","tone":3},{"hanzi":"去","text":"qù","tone":4}]'::jsonb, '3-0-4-3-4', '一起 goes before the verb — "together do something".', '一起 diletakkan sebelum kata kerja — "bersama melakukan sesuatu".', null, 2, array['plans', 'beginner']::text[], true)
insert into public.intro_cards (pack_id, external_id, title_en, title_id, body_en, body_id, example, order_index) values
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_001_what_is_mandarin', 'What is Mandarin?', 'Apa itu Mandarin?', 'Mandarin is built from sounds, tones, and characters.', 'Mandarin terdiri dari bunyi, nada, dan karakter.', null, 1),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_002_pinyin', 'Pinyin', 'Pinyin', 'Pinyin helps you read Mandarin pronunciation using Latin letters.', 'Pinyin membantu kamu membaca pelafalan Mandarin dengan huruf Latin.', '{"simplified":"你好","traditional":"你好","pinyin":"nǐ hǎo","meaning":"hello","meaning_id":"halo"}'::jsonb, 2),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_003_tones', 'Tones', 'Nada', 'Mandarin uses tones. The same sound can mean different things if the tone changes.', 'Mandarin memakai nada. Bunyi yang sama bisa punya arti berbeda kalau nadanya berubah.', '{"pinyin":["mā","má","mǎ","mà","ma"],"tones":[1,2,3,4,0]}'::jsonb, 3),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_004_tone_sandhi', 'Tone sandhi', 'Tone sandhi', 'Sometimes tones shift in natural speech. The app will point this out when it matters.', 'Kadang nada berubah saat diucapkan natural. App ini akan memberi catatan saat hal itu penting.', '{"written":"nǐ hǎo = 3-3","spoken_note":"often sounds closer to 2-3"}'::jsonb, 4),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_005_hanzi', 'Hanzi', 'Hanzi', 'Hanzi are Mandarin characters. Some are built from smaller components.', 'Hanzi adalah karakter Mandarin. Beberapa tersusun dari komponen kecil.', '{"simplified":"好","components":["女","子"],"meaning":"good"}'::jsonb, 5),
  ((select id from seed_pack_ids where external_id = 'pack_000_introduction_to_mandarin'), 'intro_006_app_flow', 'How this app works', 'Cara kerja app ini', 'Short lessons, quick practice, reviews, and unlocks help you build Mandarin step by step.', 'Pelajaran singkat, latihan cepat, review, dan unlock membantu kamu belajar bertahap.', null, 6)
